INSERT INTO scholarships (name, continent, country, level, description, deadline, category, major, benefit, requirements, source, url, original_url, embedding) VALUES ('Singapore Geomatics Scholarship', 'Asia, Eropa, Amerika, Afrika, Australia / Oceania', 'Luar Negeri (Korea Selatan, Hong Kong, New Zealand, Arab Saudi, Afrika Selatan, Inggris, Amerika Serikat, Australia, Taiwan, Jepang, Korea, Belanda, Jerman, Swiss, Singapura, Malaysia, Turki, Kanada, Perancis, Qatar, China, Swedia, Belgia, Austria, Norwegia, Denmark, Finlandia, Italia, Spanyol, Portugal, Brasil, Meksiko, Rusia, Hungaria, Yunani, Irlandia)', 'S1', 'Beasiswa - Singapore Geomatics Scholarship untuk jenjang S1 dengan tipe Fully Funded di United Arab Emirates, Austria, Australia, Belgium, Brazil, Canada, Switzerland, Chile, China, Germany, Denmark, Spain, Finland, France, United Kingdom, Greece, Hong Kong, Hungary, Ireland, Italy, Japan, South Korea, Luxembourg, Mexico, Malaysia, Netherlands, Norway, New Zealand, Portugal, Qatar, Russia, Saudi Arabia, Sweden, Singapore, Turkey, Taiwan, United States, South Africa', '31 Maret 2026', 'Fully Funded', 'Teknik, Geography, Geomatic Engineering, Geography and Environmental Science, Geographic Information Systems, Teknologi Informasi, Ilmu Komputer', '• Award Coverage: • Tuition & compulsory university fees • Maintenance allowance • Overseas Student Exchange programme • Return airfare (where applicable) • While studying, you will have: • A mentor assigned to you • Internship opportunities with SLA • Opportunities to participate in SLA activities, such as D&D • Email updates on SLA happenings and events • While in service, you will have: • Build a specialist professional career in a growing and thriving industry • Plug into the latest geospatial technological arena • Attend the latest geospatial seminars and programmes • Serve as evangelists to promote the growth and development of the geospatial and geospatial-related technologies in the public sector and geospatial industry • Have opportunities to learn from the expertise of 9 public agencies', 'AGE No age requirement GPA No GPA requirement ENGLISH TEST Not required NATIONALITY Indonesian OTHER LANGUAGE Not required STANDARDIZED TEST Standardized Test (Required) A-Level, IB DOCUMENTS 1. Singapore Citizenship 2. Academic results 3. CCA OTHERS Bond: 4 years (local study) 6 years (overseas study)', 'Schoters', 'https://www.schoters.com/id/beasiswa/singapore-geomatics-scholarship-166', 'https://www.sutd.edu.sg/admissions/graduate/scholarship/sutd-graduate-fellowships-scholarships/', '[0.04149120673537254, 0.000307838199660182, 0.06815659254789352, -0.0137877082452178, 0.038942452520132065, -0.12165766954421997, -0.04378007352352142, 0.007602057419717312, -0.042980510741472244, 0.05010460317134857, 0.004419561475515366, -0.0729195699095726, 0.01031543593853712, 0.029175439849495888, -0.049100350588560104, -0.0032662502489984035, -0.0952073484659195, 0.010374621488153934, -0.05890610069036484, -0.07181493192911148, -0.0018051781225949526, -0.027988065034151077, 0.009763699024915695, -0.004242710303515196, 0.004624783527106047, -0.052560362964868546, -0.01322716474533081, 0.03614093363285065, -0.0074819885194301605, -0.010107384994626045, -0.042033128440380096, 0.14758498966693878, -0.048506710678339005, 0.033196959644556046, 0.02046070247888565, 0.05581261217594147, -0.044268250465393066, -0.03561747074127197, -0.05754932016134262, 0.023069558665156364, -0.02952517941594124, 0.00990775041282177, 0.051574308425188065, -0.006724126636981964, 0.026105470955371857, -0.033427782356739044, 0.012365399859845638, -0.04280276224017143, -0.05621545761823654, 0.007162232883274555, -0.06626627594232559, -0.010017183609306812, -0.05643221363425255, -0.014988075941801071, -0.0548987090587616, -0.016127631068229675, 0.03659212589263916, -0.0024311020970344543, -0.06597769260406494, -0.041909512132406235, 0.056082870811223984, -0.004620830994099379, -0.09882678836584091, 0.018027231097221375