INSERT INTO scholarships (name, continent, country, level, description, deadline, category, major, benefit, requirements, source, url, original_url, embedding) VALUES ('Singapore Geospatial Scholarship', 'Asia, Eropa, Amerika, Afrika, Australia / Oceania', 'Luar Negeri (Korea Selatan, Hong Kong, New Zealand, Arab Saudi, Afrika Selatan, Inggris, Amerika Serikat, Australia, Taiwan, Jepang, Korea, Belanda, Jerman, Swiss, Singapura, Malaysia, Turki, Kanada, Perancis, Qatar, China, Swedia, Belgia, Austria, Norwegia, Denmark, Finlandia, Italia, Spanyol, Portugal, Brasil, Meksiko, Rusia, Hungaria, Yunani, Irlandia)', 'S1', 'Beasiswa - Singapore GeoSpatial Scholarship untuk jenjang S1 dengan tipe Fully Funded di United Arab Emirates, Austria, Australia, Belgium, Brazil, Canada, Switzerland, Chile, China, Germany, Denmark, Spain, Finland, France, United Kingdom, Greece, Hong Kong, Hungary, Ireland, Italy, Japan, South Korea, Luxembourg, Mexico, Malaysia, Netherlands, Norway, New Zealand, Portugal, Qatar, Russia, Saudi Arabia, Sweden, Singapore, Turkey, Taiwan, United States, South Africa', '31 Maret 2026', 'Fully Funded', 'Teknik, Geography, Geomatic Engineering, Geography and Environmental Science, Geographic Information Systems, Teknologi Informasi, Ilmu Komputer', '• Award Coverage: • Tuition & compulsory university fees • Maintenance allowance • Overseas Student Exchange programme • Return airfare (where applicable) • While studying, you will have: • A mentor assigned to you • Internship opportunities with SLA • Opportunities to participate in SLA activities, such as D&D • Email updates on SLA happenings and events • While in service, you will have: • Build a specialist professional career in a growing and thriving industry • Plug into the latest geospatial technological arena • Attend the latest geospatial seminars and programmes • Serve as evangelists to promote the growth and development of the geospatial and geospatial-related technologies in the public sector and geospatial industry • Have opportunities to learn from the expertise of 9 public agencies', 'AGE No age requirement GPA No GPA requirement ENGLISH TEST Not required NATIONALITY Indonesian OTHER LANGUAGE Not required STANDARDIZED TEST Standardized Test (Required) A-Level, IB DOCUMENTS 1. Singapore Citizenship 2. Academic results 3. CCA OTHERS Bond: 4 years (local study) 6 years (overseas study)', 'Schoters', 'https://www.schoters.com/id/beasiswa/singapore-geospatial-scholarship-167', 'https://www.sutd.edu.sg/admissions/graduate/scholarship/sutd-graduate-fellowships-scholarships/', '[0.0373261421918869, -0.0014721174957230687, 0.06831391900777817, 0.0009668406564742327, 0.041641805320978165, -0.1288924664258957, -0.05300823226571083, 0.00430943863466382, -0.04310425743460655, 0.04138591140508652, 0.005556529853492975, -0.08295827358961105, 0.0033133020624518394, 0.029254883527755737, -0.05058829113841057, -0.0048960130661726, -0.1020030528306961, 0.009052930399775505, -0.05345093831419945, -0.07172452658414841, -0.007419802714139223, -0.03763421252369881, 0.007958769798278809, -0.004977989476174116, 0.009692505933344364, -0.056262850761413574, -0.011062401346862316, 0.044143274426460266, -0.012426515109837055, -3.981265763286501e-05, -0.05177474766969681, 0.13989253342151642, -0.051888734102249146, 0.04665436968207359, 0.02110517956316471, 0.0649576336145401, -0.049356043338775635, -0.031082872301340103, -0.046473126858472824, 0.01429424062371254, -0.02354249358177185, 0.007474490907043219, 0.05589323490858078, -0.01569431461393833, 0.038075339049100876, -0.029702944681048393, 0.025646012276411057, -0.03776770830154419, -0.05173055827617645, 0.008380160667002201, -0.05234226584434509, -0.004917461890727282, -0.06180264428257942, -0.017864661291241646, -0.05729101598262787, -0.027644416317343712, 0.036651771515607834, -0.006428145337849855, -0.05251067131757736, -0.03793899714946747, 0.049792442470788956, -0.006568145006895065, -0.09694205224514008, 0.02164873480796814, 