INSERT INTO scholarships (name, continent, country, level, description, deadline, category, major, benefit, requirements, source, url, original_url, embedding) VALUES ('University Of Science And Technology Of China Ustc Fellowship For Undergraduate Programs Chinese Taught', 'Asia', 'Luar Negeri (China)', 'S1', 'Beasiswa - University of Science and Technology of China - USTC Fellowship for Undergraduate Programs (Chinese Taught) untuk jenjang S1 dengan tipe Fully Funded, Partially Funded di China', '31 Maret 2026', 'Fully Funded', 'Matematika, Applied Mathematics, Fisika, Applied Physics, Astronomi, Keuangan, Statistika, Administrasi Bisnis, Kimia, Material Physics, Polymer Science and Engineering, Bioscience, Bioteknologi, Geophysics, Atmospheric Sciences, Planetary Geosciences, Energy Engineering, Energy and Power Engineering, Robotics, "Health, Safety and Environmental Engineering", Electronic Information Engineering, Electronic Science and Technology, Integrated Circuit Design and Integrated System, Automation, Nuclear Engineering, Physicist Engineering, Computer Science and Technology, Kecerdasan Buatan, Quantum System Engineering, Cybersecurity, Information Security, Environmental Science and Engineering', '• ● Level A, funded by USTC, includes tuition waiver, comprehensive medical insurance, monthly stipend of 2,500 RMB and accommodation subsidy; • ● Level B, funded by USTC, includes tuition waiver.', 'AGE Max Age: 30 GPA No GPA requirement ENGLISH TEST Not required NATIONALITY Indonesian OTHER LANGUAGE HSK: HSK Level 5 STANDARDIZED TEST Not required DOCUMENTS ● Application Form for International Students (Undergraduate Program) (Annex II) ● Photocopy of passport (including pages with Chinese visa or residence permit, if applicable) ● Notarized photocopies of senior high school graduation certificate and transcripts. Applicants who will be graduating from senior high school before July 2025 should provide Pre-graduation Certificate issued by senior high school