INSERT INTO scholarships (name, continent, country, level, description, deadline, category, major, benefit, requirements, source, url, original_url, embedding) VALUES ('Master Mind Scholarship Vrije Universiteit Brussel', 'Eropa', 'Luar Negeri (Belgia)', 'S2', 'Beasiswa - Master Mind Scholarship - Vrije Universiteit Brussel untuk jenjang S2 dengan tipe Fully Funded di Belgium', '26 Maret 2026', 'Fully Funded', 'Fisika, Kimia, Astronomi, Biologi, Ilmu Biologi, Ilmu Biomedis, Teknik Elektro, Teknik Mesin, Teknik Komputer, Teknik Sipil, Teknik Kimia, Nuclear, Studi Komunikasi, Linguistik, Jurnalistik, Ilmu Komputer, Administrasi Bisnis, Manajemen Bisnis, Arsitektur, Ilmu Politik', '• Fixed amount: €10.020 per academic year • Tuition fee/tuition waiver: Tuition fee is limited to amount paid by Flemish scholarship student. For 2025-2026: €139,40 • Duration (in months or weeks): Duration of the Master program (if 2-year Master: second year conditional). • Health insurance included? No. • Flight (per year or total for the period)? No • Language preparation courses (up to X weeks or amount)? No.', 'AGE No age requirement GPA Min. GPA: 3.5 out of 4.00 ENGLISH TEST IELTS: min. 7 TOEFL iBT: min. 94 NATIONALITY Indonesian OTHER LANGUAGE Not required STANDARDIZED TEST Not required DOCUMENTS application form (download here); Passport photo; International passport or national registration card; Transcript of records; if written in another language than Dutch, French or English, a certified translation must be enclosed. A Curriculum Vitae (including your American GPA out of 4.0 and if applicable your publications, academic awards, previous scholarships, etc.) Screenshots of all steps of your calculation of your GPA through the website provided. (https://www.scholaro.com/gpa-calculator/) English language test results. Online language tests of IELTS and TOEFL will also be accepted: IELTS Indicator (https://www.ieltsindicator.com/) TOEFL iBT Special Home Edition (https://www.ets.org/s/cv/toefl/at-home/) Letter of motivation written in English (towards the jury of the Flemish Government) Two', 'Schoters', 'https://www.schoters.com/id/beasiswa/master-mind-scholarship-vrije-universiteit-brussel-180', 'https://www.studyinflanders.be/scholarships/master-mind-scholarships', '[0.019707800820469856, -0.002054608426988125, 0.01656549610197544, -0.03533611819148064, 0.0018542881589382887, -0.005491345655173063, -0.006038738880306482, 0.015054309740662575, 0.08024752140045166, 0.039048533886671066, -0.005305396858602762, -0.05400031432509422, -0.06723830103874207, -0.01701739802956581, -0.0030783547554165125, 0.06022623926401138, -0.06188373267650604, 0.004173357971012592, -0.06660456210374832, -0.002454728353768587, -0.031563468277454376, -0.01859198324382305, 0.07356729358434677, -0.04002217948436737, -0.055576711893081665, 0.054395586252212524, 0.006794115528464317, -0.050353869795799255, 0.006975800730288029, 0.0016232180641964078, 0.04734247177839279, 0.10948239266872406, -0.08795645087957382, -0.022603090852499008, -0.02764800749719143, 0.03621349856257439, -0.08484532684087753, -0.040386732667684555, 0.013014751486480236, -0.021086435765028, -0.06286148726940155, -0.05456724762916565, -0.04327365756034851, -0.04812629893422127, 0.04537292197346687, -0.02398756518959999, -0.04206210747361183, -0.026726240292191505, -0.06033126637339592, -0.06329179555177689, -0.14494870603084564, -0.0553986057639122, 0.0177176333963871, 0.022686872631311417, 0.023778853937983513, -0.00883735716342926, -0.04807807877659798, 0.03421536460518837, -0.07555434107780457, 0.013605489395558834, 0.029110314324498177, 0.0015629793051630259, -0.038641225546598434, -0.007771342992782593, 0.024819793179631233, -0.02307608351111412, -0.07437055557966232, 0.04664059728384018, -0.002154364250600338, 0.03197604417800903, 0.031790684908628464, -0.028374923393130302, -0.04394867271184921, 0.05809415131807327, 0.01471772976219654, 0.05930810794234276, 0.01461099088191986, 0.006433389615