INSERT INTO scholarships (name, continent, country, level, description, deadline, category, major, benefit, requirements, source, url, original_url, embedding) VALUES ('National Library Board Nlb Scholarship', 'Asia, Eropa, Amerika, Afrika, Australia / Oceania', 'Luar Negeri (Korea Selatan, Hong Kong, New Zealand, Arab Saudi, Afrika Selatan, Inggris, Amerika Serikat, Australia, Taiwan, Jepang, Korea, Belanda, Jerman, Swiss, Singapura, Malaysia, Turki, Kanada, Perancis, Qatar, China, Swedia, Belgia, Austria, Norwegia, Denmark, Finlandia, Italia, Spanyol, Portugal, Brasil, Meksiko, Rusia, Hungaria, Yunani, Irlandia)', 'S1', 'Beasiswa - National Library Board (NLB) Scholarship untuk jenjang S1 dengan tipe Fully Funded di United Arab Emirates, Austria, Australia, Belgium, Brazil, Canada, Switzerland, Chile, China, Germany, Denmark, Spain, Finland, France, United Kingdom, Greece, Hong Kong, Hungary, Ireland, Italy, Japan, South Korea, Luxembourg, Mexico, Malaysia, Netherlands, Norway, New Zealand, Portugal, Qatar, Russia, Saudi Arabia, Sweden, Singapore, Turkey, Taiwan, United States, South Africa', '15 April 2026', 'Fully Funded', 'Bisnis, Literature, Digital Humanities and Computational Social Sciences, Chinese Language, Sejarah, Southeast Asian Studies, Information Science and Technology', '• This is a fully-funded scholarship with the following value and benefits: • Tuition and other compulsory fees • Monthly maintenance allowance • Other allowance e.g. pre-studies allowance • Return airfare (for overseas studies) • Opportunity for sponsorship of approved student exchange/summer school programme • Internship opportunities', 'AGE No age requirement GPA No GPA requirement ENGLISH TEST Not required NATIONALITY Indonesian OTHER LANGUAGE Not required STANDARDIZED TEST Standardized Test (Required) A-Level, IB DOCUMENTS You would be required to have a good academic and Co-Curricular Activities (CCAs) records, strong leadership qualities, good interpersonal skills and a passion for learning and service You must be a Singapore Citizen or Singapore Permanent Resident who intends to take up Singapore citizenship OTHERS You can choose to do your undergraduate studies in Singapore or at renowned universities overseas.  Bond Period: - 4 years for universities in Singapore - 5 years for universities in non-English speaking countries (e.g. China) - 6 years for universities in English-speaking countries (e.g. US, UK and Australia) - Mid-term Scholarship: 1 year per year of local sponsored study and 1.5 years per year of overseas sponsored study', 'Schoters', 'https://www.schoters.com/id/beasiswa/national-library-board-nlb-scholarship-184', 'https://www.nlb.gov.sg/main/about-us/careers/scholarship', '[0.025839393958449364, -0.08112934231758118, -0.013214210979640484, -0.015969587489962578, 0.06192952021956444, -0.045082222670316696, -0.04338575899600983, -0.009714026004076004, 0.07843150198459625, 0.020783664658665657, 0.025161925703287125, -0.001602735137566924, 0.02502620220184326, -0.045324258506298065, -0.02797284722328186, -0.018110958859324455, -0.046453844755887985, -0.042497701942920685, -0.11599832773208618, -0.0887201726436615, -0.011296153999865055, 0.003922035451978445, 0.074268639087677, -0.01701764389872551, 0.048647165298461914, -0.0857904776930809, -0.04987001419067383, -0.005202517844736576, -0.03110363520681858, -0.02541607804596424, 0.006912235636264086, 0.14118655025959015, 0.033739302307367325, 0.07113633304834366, -0.007067846134305, 0.043210506439208984, -0.005749437026679516, -0.010384766384959221, 0.001344202901236713, 0.00025242107221856713, -0.07177207618951797, -0.01425259467214346, 0.0013818981824442744, -0.01874912716448307, 0.06020020693540573, -0.014745683409273624, -0.04572409391403198, -0.009418080560863018, -0.09485407918691635, 0.06277843564748764, -0.11193396896123886, -0.020405907183885574, 0.03655809536576271, 0.08393676578998566, -0.014235738664865494, 0.024343153461813927, -0.014083116315305233, 0.0466199