INSERT INTO scholarships (name, continent, country, level, description, deadline, category, major, benefit, requirements, source, url, original_url, embedding) VALUES ('Asean Undergraduate Scholarship Singapore Institute Of Technology Sit Ib Diploma', 'Asia', 'Luar Negeri (Singapura)', 'S1', 'Beasiswa - ASEAN Undergraduate Scholarship - Singapore Institute of Technology (SIT) - IB Diploma untuk jenjang S1 dengan tipe Fully Funded di Singapore', '19 Maret 2026', 'Fully Funded', 'Akuntansi, Transportation Sciences, Kecerdasan Buatan, FinTech, IT and Computing, Teknik Kimia, Teknik Sipil, Teknik Komputer, Game Design & Technology, Ilmu Komputasi, Ilmu Pangan dan Gizi, Animasi, Media Communication, Manajemen Rantai Pasok dan Logistik, Electrical and Electronic Engineering, Power and Electrical Engineering, Engineering Systems and Management, Food Science and Technology, Kuliner, Industri Perhotelan dan Pariwisata, Information and Communication Technology, Software Engineering, Infrastructure & Project Management, Mechanical Design, Teknik Mesin, Naval Architecture & Ocean Engineering, Keperawatan, Terapi Okupasi, Pharmaceutical Science, Fisioterapi, Robotics, Sustainability Science, Creative Media and Game Technologies', '• Subsidised tuition fees • Living allowance of S$5,800 per annum • Accommodation allowance of S$3,000 per annum • One-time laptop allowance of S$1,750', 'AGE Min Age: 18 GPA Min. GPA: 3.5 out of 4.00 ENGLISH TEST IELTS: min. 7 TOEFL iBT: min. 90 NATIONALITY Indonesian OTHER LANGUAGE Not required STANDARDIZED TEST Standardized Test (Recommended) SAT, ACT SAT: 650 ACT: 29 DOCUMENTS Applicants submitting the International Baccalaureate Diploma must fulfil the following requirements: Obtain a grade five in at least two Higher Level (HL) and one Standard Level (SL) subjects Obtain the IB Diploma In addition, applicants must meet one of the following Mother Tongue Language (MTL) requirements: A minimum pass grade for HL/SL MTL A: Literature A minimum pass grade for HL/SL MTL A: Language and Literature A minimum pass grade for HL/SL Language B A minimum D7 for the higher MTL paper taken at the ''O'' Level examination International Students (IS) in Privately-Funded Schools (PFS) are not required to fulfil the MTL Requirement. Please check first. OTHERS No other specific requirements mentioned.', 'Schoters', 'https://www.schoters.com/id/beasiswa/asean-undergraduate-scholarship-singapore-institute-of-technology-sit-ib-diploma-198', 'https://www.singaporetech.edu.sg/admissions/scholarships/asean-undergraduate-scholarship-aus', '[-0.06588742882013321, 0.0027782621327787638, 0.0272733923047781, -0.05422546714544296, 0.011984536424279213, -0.06692065298557281, -0.02193453721702099, 0.009778683073818684, -0.034274064004421234, 0.047524090856313705, -0.00242684967815876, -0.09519769996404648, 0.035139523446559906, -0.03615913540124893, -0.0031004836782813072, -0.05752212926745415, -0.01623067632317543, -0.0800444483757019, -0.03598955273628235, -0.08830036222934723, -0.00925371516495943, -0.05327238887548447, 0.03145195171236992, -0.051957182586193085, -0.0323161855340004, -0.03487301245331764, 0.03073257766664028, 0.034964751452207565, -0.059715211391448975, -0.037236519157886505, -0.08665082603693008, 0.11946465075016022, -0.02800784818828106, 0.05925397202372551, 0.04110986739397049, 0.049852918833494186, -0.03810051083564758, -0.06397855281829834, -0.01636486127972603, -0.05090996250510216, -0.07381314039230347, -0.03234895318746567, -0.00770470779389143, -0.03401991352438927, 0.10092176496982574, -0.11068925261497498, -0.08422545343637466, -0.07838127762079239, -0.04076139256358147, 0.04283447563648224, -0.0835854634642601, 0.02572433091700077, 0.0324319452047348, -0.017735647037625313, -0.0382661335170269, -0.01472873892635107, 0.02370859868824482, 0.04062604904174805, -0.024134645238518715, -0.02560657449066639, 0.033132389187812805, -0.018570056185126305, -0.027758045122027397, 0.03796377032995224, 0.034808021038770676,