INSERT INTO scholarships (name, continent, country, level, description, deadline, category, major, benefit, requirements, source, url, original_url, embedding) VALUES ('Daad Epos International Media Studies Hs Bonn Rhein Sieg Dw Akademie U Bonn', 'Eropa', 'Luar Negeri (Jerman)', 'S2', 'Beasiswa - DAAD EPOS - International Media Studies - HS Bonn-Rhein-Sieg/DW Akademie/U Bonn untuk jenjang S2 dengan tipe Fully Funded di Germany', '15 Maret 2026', 'Fully Funded', 'Studi Komunikasi, Jurnalistik, Media and, Media Management', '• Depending on academic level, monthly payments of 934 euros for graduates or 1,200 euros for doctoral candidates • Payments towards health, accident and personal liability insurance cover • Travel allowance, unless these expenses are covered by the home country or another source of funding • Under certain circumstances, scholarship holders may receive the following additional benefits: • Monthly rent subsidy • Monthly allowance for accompanying members of family', 'AGE No age requirement GPA No GPA requirement ENGLISH TEST IELTS: min. 7 NATIONALITY Indonesian OTHER LANGUAGE DSH: DSH 1 STANDARDIZED TEST Not required DOCUMENTS Completed and signed checklist DAAD application “Application for a research/study scholarship” (please type your answers or make sure they are easy to read) A curriculum vitae in reverse chronological order without any unexplained gaps (please use the europass template (mandatory) including exact information about your studies, and on practical experience) One Letter of Motivation with detailed reference to academic, professional and personal reasons for applying for the programme. IMPORTANT: When applying for more than one postgraduate course (maximum 3 courses), please also give detailed reasons for your choice of courses and prioritisation in the letter of motivation. Please submit the same letter of motivation to all postgraduate degree programmes of your choice. Letter of recommendation from your current employer; the le', 'Schoters', 'https://www.schoters.com/id/beasiswa/daad-epos-international-media-studies-hs-bonn-rhein-sieg-dw-akademie-u-bonn-211', 'https://www.mfa.gov.sg/careers/foreign-service-scholarships/', '[0.005591115914285183, -0.007661827839910984, -0.0029388354159891605, -0.03685246780514717, 0.07982137799263, 0.035873547196388245, -0.001883645192719996, 0.013126925565302372, 0.016210263594985008, 0.06516283005475998, 0.023875966668128967, 0.003654641332104802, -0.01409897580742836, -0.003507991787046194, 0.007610832341015339, -0.06595849990844727, -0.024233397096395493, -0.07404429465532303, -0.06965162605047226, -0.07012636959552765, -0.03485630452632904, -0.0681850016117096, 0.08460308611392975, -0.03005058690905571, 0.0223787073045969, -0.06585212051868439, -0.01382406149059534, 0.02143341675400734, -0.0034845080226659775, -0.04429909586906433, 0.06887051463127136, 0.03479742631316185, -0.012417091056704521, -0.009428102523088455, 0.061106935143470764, 0.007749566808342934, -0.012675239704549313, -0.07691047340631485, -0.0789058655500412, 0.0599985234439373, -0.014456363394856453, -0.024385245516896248, -0.025228183716535568, -0.08667907118797302, -0.037192996591329575, -0.023801112547516823, -0.0015628586988896132, 0.0802430510520935, -0.07881665974855423, 0.05277299880981445, 0.0018734470941126347, -0.04497653245925903, 0.08512793481349945, 0.03010246343910694, 0.04677914083003998, -0.057323165237903595, -0.04001620411872864, 0.0956733226776123, 0.02045142836868763, 0.004365330096334219, -0.02668817713856697, -0.03109920397400856, -0.10143721103668213, 0.02186664566397667, 0.015397189185023308, 0.02635759301483631, 0.03805355355143547, 0.08704572916030884, -0.08986818790435791, -0.016085315495729446, 0.041334182024002075, -0.05509401112794876, -0.04724867641925812, 0.1357562094926834, 0.04311300441622734, -0.09183470904827118, 0.012135777622461319, 0.102080799639225, 0.11698722839355469, -0.04157013073563576, 0.09746726602315903, -0.036514345556497574, 0.0371230