INSERT INTO scholarships (name, continent, country, level, description, deadline, category, major, benefit, requirements, source, url, original_url, embedding) VALUES ('Government Of Ireland International Education Scholarships Goi Ies', 'Eropa', 'Luar Negeri (Irlandia)', 'S2', 'Beasiswa - Government of Ireland - International Education Scholarships (GOI-IES) untuk jenjang S2 dengan tipe Fully Funded di Ireland', '12 Maret 2026', 'Fully Funded', 'Matematika, Statistika, Fisika, Ilmu Kebumian, Kimia, Ilmu Alam Terapan, Astronomi, Ilmu Biologi, Bioteknologi, Studi Pertanian, Ilmu Pangan, Kelautan / Kehutanan, Akuakultur, Psikologi Klinis, Ilmu Kedokteran, Ilmu Biomedis, Kesehatan Masyarakat, Farmasi, Kedokteran Hewan, Teknik Elektro, Teknik Mesin, Teknik Robotika, Teknik Komputer, Teknik Sipil, Teknik Kimia, Teknik Dirgantara, Teknik Pertambangan dan Perminyakan, Teknik Industri, Teknik Umum, Ilmu Material dan Teknik, Teknik Lingkungan, Psikologi, Hukum dan Studi Hukum, Bahasa dan Sastra, Antropologi, Studi Komunikasi, Studi Budaya dan Agama, Filsafat, Mode / Fashion, Desain Visual, Desain Produk, Seni Rupa, Musik, Seni Pertunjukan, Keuangan, Ekonomi, Perpajakan, Akuntansi, Ilmu Komputer, Ilmu Data, Kecerdasan Buatan, Sistem Informasi, Teknologi Informasi, Teknologi Digital, Administrasi Bisnis, Manajemen Bisnis, Pemasaran, Perubahan Iklim, Manajemen Sumber Daya Alam, Manajemen Energi, Studi Lingkungan Umum, Arsitektur, Perencanaan Kota, Desain Interior, Pendidikan Bahasa, Pendidikan Umum, Pariwisata, Kuliner, Manajemen Perhotelan, Pemerintahan, Hubungan Internasional, Administrasi Publik', '• A Government of Ireland International Education Scholarship consists of a stipend amounting to €10,000 for one year of full-time study at NFQ levels 9 or 10.  The awardees’ host higher education institutions are required to give a full fee waiver to the awardees for the year of their scholarship.', 'AGE No age requirement GPA No GPA requirement ENGLISH TEST Not required NATIONALITY Indonesian OTHER LANGUAGE Not required STANDARDIZED TEST Not required DOCUMENTS Academic qualifications, achievements and/or work experience Personal Statement Two references uploaded via the online application portal. LoA (conditional or unconditional) OTHERS Test requirement based on the selected program  • a record of outstanding academic achievement; • excellent communication skills; • evidence of participation in extracurricular activities, for example, humanitarian work, politics, arts or sport; and • a strong rationale for pursuing their study in Ireland that indicates how a GOIIES would align with their longer-term goals.', 'Schoters', 'https://www.schoters.com/id/beasiswa/government-of-ireland-international-education-scholarships-goi-ies-231', 'https://hea.ie/policy/internationalisation/goi-ies/', '[-0.035734158009290695, 0.02459898591041565, -0.027227284386754036, -0.06832122802734375, 0.02446398138999939, -0.005617194809019566, -0.05887467414140701, 0.038992371410131454, 0.05725187808275223, 0.040822453796863556, 0.044652968645095825, -0.04424429312348366, -0.08775638043880463, 0.004804312251508236, -0.09024828672409058, -0.025885988026857376, -0.048361312597990036, -0.029814328998327255, -0.06461482495069504, -0.07336357235908508, 0.04168142378330231, 0.03697088733315468, 0.03074769116938114, -0.006649641785770655, -0.027449168264865875, -0.06848444044589996, 0.018977034837007523, -0.06366866827011108, 0.03498421236872673, -0.005895550362765789, 0.03475450351834297, 0.04416852444410324, -0.08034180104732513, 0.010263820178806782, 0.04081657528877258, 0.058898601680994034, -0.025583436712622643, -0.016149448230862617, -0.0017125133890658617, 0.021898088976740837, -0.04543837904930115, -0.062291212379932404, -0.035681914538145065, 0.0005747791728936136, 0.14629888534545898, 0.014627870172262192, -0.06738076359033585, -0.09672600030899048, -0.03409428521990776, -0.0335957407951355, -0.12669621407985687, -0.0316767543554306, 0.011844209395349026, 0.00889