INSERT INTO scholarships (name, continent, country, level, description, deadline, category, major, benefit, requirements, source, url, original_url, embedding) VALUES ('Kyoto University Of Advanced Science Kuas Super Kuas E Scholarship', 'Asia', 'Luar Negeri (Jepang)', 'S1', 'Beasiswa - Kyoto University of Advanced Science (KUAS) - Super KUAS-E Scholarship untuk jenjang S1 dengan tipe Fully Funded di Japan', '6 Maret 2026', 'Fully Funded', 'Teknik Mesin, Teknik Elektro, Ilmu Lingkungan, Bioresources Sciences, Ilmu Biologi, Global Business Administration, Ekonomi', '• Stipend (for personal expenses) 1,200,000 JPY/year* • Tuition exemption 100% • Admission fee exemption 100%', 'AGE No age requirement GPA No GPA requirement ENGLISH TEST IELTS: min. 6 TOEFL iBT: min. 75 Duolingo NATIONALITY Indonesian OTHER LANGUAGE Not required STANDARDIZED TEST Standardized Test (Required) SAT DOCUMENTS 1. Photograph (.jpeg) 2. Application essay (300 words minimum, 350 words maximum) 3. Essay for Faculty of Bioenvironmental Sciences (200 words minimum, 250 words maximum / only required for Faculty of Bioenvironmental Sciences) 4. Official academic transcript(s) for the last two years 5. Certificates of (expected) graduation 6. Standardized test results (MANDATORY: Faculty of Engineering, OPTIONAL:Faculty of Bioenvironmental Sciences / Faculty of Economics and Business Administration) 7. Evidence of English language proficiency（TOEFL iBT / IELTS / PTE / Duolingo） 8. A letter of recommendation 9. Copy of your passport or ID 10. Copy of residence card (only for the applicants who have valid Japanese resident status) OTHERS No other specific requirements mentioned.', 'Schoters', 'https://www.schoters.com/id/beasiswa/kyoto-university-of-advanced-science-kuas-super-kuas-e-scholarship-244', 'https://www.kuas.ac.jp/en/admission/scholarship/', '[-0.056517042219638824, -0.0074858712032437325, -0.010302546434104443, -0.04026976600289345, 0.02338237501680851, -0.0029618367552757263, -0.0737000852