INSERT INTO scholarships (name, continent, country, level, description, deadline, category, major, benefit, requirements, source, url, original_url, embedding) VALUES ('Lee Kuan Yew Scholarship', 'Asia, Eropa, Amerika, Afrika, Australia / Oceania', 'Luar Negeri (Korea Selatan, Hong Kong, New Zealand, Arab Saudi, Afrika Selatan, Inggris, Amerika Serikat, Australia, Taiwan, Jepang, Korea, Belanda, Jerman, Swiss, Singapura, Malaysia, Turki, Kanada, Perancis, Qatar, China, Swedia, Belgia, Austria, Norwegia, Denmark, Finlandia, Italia, Spanyol, Portugal, Brasil, Meksiko, Rusia, Hungaria, Yunani, Irlandia)', 'S2', 'Beasiswa - Lee Kuan Yew Scholarship untuk jenjang S2 dengan tipe Fully Funded di United Arab Emirates, Austria, Australia, Belgium, Brazil, Canada, Switzerland, Chile, China, Germany, Denmark, Spain, Finland, France, United Kingdom, Greece, Hong Kong, Hungary, Ireland, Italy, Japan, South Korea, Luxembourg, Mexico, Malaysia, Netherlands, Norway, New Zealand, Portugal, Qatar, Russia, Saudi Arabia, Sweden, Singapore, Turkey, Taiwan, United States, South Africa', '28 Februari 2026', 'Fully Funded', 'All Majors', '• Scholarship recipients will receive full tuition fees coverage and an annual allowance of S$50,000 for up to 2 years if they are pursuing a Master’s degree or up to 5 years for PhD studies. • Public sector awardees who are already sponsored by their agencies for their postgraduate studies will receive a one-off sum of S$10,000. They will not receive sponsorship of tuition fees and the annual allowance from the Lee Kuan Yew Scholarship.', 'AGE No age requirement GPA No GPA requirement ENGLISH TEST Not required NATIONALITY Indonesian OTHER LANGUAGE Not required STANDARDIZED TEST Not required DOCUMENTS 1. Certificates of Academic Qualifications Obtained 2. Full University Transcript(s) and Degree Certificate(s) 3. Co-curricular Activities and Achievement Records 4. List of Publications/ Conferences/ Presentations (if applicable) 5. NS Certificate of Service and Service Transcript (if applicable) 6. Certificate of Singapore Citizenship by Registration (if applicable) 7. Letters of Admission to Universities (if applicable) 8. 2 Reference letters 9. Essay OTHERS No other specific requirements mentioned.', 'Schoters', 'https://www.schoters.com/id/beasiswa/lee-kuan-yew-scholarship-287', 'https://www.psc.gov.sg/scholarships/postgraduate-scholarships/lee-kuan-yew-scholarship', '[-0.0002544269373174757, -0.027099119499325752, -0.013906893320381641, -0.03770323470234871, 0.03873782977461815, -0.04591849073767662, -0.06269735097885132, 0.017410600557923317, -0.003186263842508197, 0.021709270775318146, 0.008766746148467064, -0.016284894198179245, -0.058720655739307404, -0.041800759732723236, -0.0250394269824028, -0.039662037044763565, -0.037977851927280426, 0.0012696990743279457, -0.08037136495113373, -0.07351857423782349, -0.027678409591317177, -0.027321627363562584, 0.06141442432999611, -0.0042193434201180935, 0.026034988462924957, -0.06597911566495895, 0.035117171704769135, 0.005327942781150341, 0.008620239794254303, -0.033534273505210876, -0.020358579233288765, 0.12078526616096497, -0.06300818175077438, 0.052223075181245804, -0.014094849117100239, 0.007248386740684509, 0.006523811258375645, -0.044301386922597885, -0.09289398044347763, 0.007098483387380838, 0.013466401025652885, -0.0005145891336724162, 0.03393955156207085, -0.047147464007139206, 0.050814952701330185, -0.06622672080993652, -0.05678899586200714, -0.034631144255399704, -0.02292894944548607, 0.06843657046556473, -0.06124900281429291, -0.010174708440899849, 0.021987836807966232, -0.015177364461123943, 0.03322329744696617, 0.02375032939016819, -0.021748337894678116, 0.024138597771525383, -0.06508591771125793, -0.015611258335411549, -0.0071284230798482895, -0.03002237342298031, -0.0641724094748497, 0.0167232658714056, -0.012999314814805984, -0.023139098659157753, -0.007990378886461258, 0.0276641808450222, -0.0007814393611624837, -0.005124381277710199, 0.01147269085