INSERT INTO scholarships (name, continent, country, level, description, deadline, category, major, benefit, requirements, source, url, original_url, embedding) VALUES ('Zhejiang University Zju Chinese Government Scholarship Youth Of Excellence Scheme Of China Yes China', 'Asia', 'Luar Negeri (China)', 'S2', 'Beasiswa - Zhejiang University (ZJU) - Chinese Government Scholarship Youth of Excellence Scheme of China (YES China) untuk jenjang S2 dengan tipe Fully Funded di China', '28 Februari 2026', 'Fully Funded', 'Energy and Power Engineering, China Studies, Ekonomi', '• 1. Tuition waiver; • 2. Free accommodation on campus; • 3. Stipend: Granted in accordance with relevant standard; • 4. Comprehensive Medical Insurance (Please refer to the relevant chapters in the application guide for details); • Note: For detailed information, please view the introduction to Chinese Government Scholarships on CSC website https://www.campuschina.org/', 'AGE Max Age: 45 GPA No GPA requirement ENGLISH TEST IELTS: min. 7 TOEFL iBT: min. 90 NATIONALITY Indonesian OTHER LANGUAGE HSK: HSK Level 5 STANDARDIZED TEST Standardized Test (Required) GMAT/GRE GRE: 320 GMAT: 550 DOCUMENTS 1.A photocopy of passport front page. The passport should be valid before December 31, 2024. 2.Highest degree certificates. If applicants are university students, they shall provide an official pre-graduation certificate. The original or notarized copy of the academic qualification certificate must be submitted after admission (the degree certificate must be obtained no later than registration). 3.Academic transcripts during Bachelor’s degree study. 4.Language proficiency certificates（Download）. 5.Personal statement, in Chinese or English, should include study and work experience, reasons for application and study proposal. No less than 1500 words. 6.Two letters of recommendation from full professors or associate professors. (Professors’ signature, contact phone nu', 'Schoters', 'https://www.schoters.com/id/beasiswa/zhejiang-university-zju-chinese-government-scholarship-youth-of-excellence-scheme-of-china-yes-china-293', 'https://iczu.zju.edu.cn/', '[-0.0885477066040039, 0.16571441292762756, 0.045342691242694855, 0.013564040884375572, 0.03315967693924904, -0.062458328902721405, -0.014460413716733456, -0.0071154991164803505, -0.04594504460692406, -0.01868210919201374, 0.052874960005283356, -0.03822700306773186, 0.03747481480240822, -0.038925960659980774, -0.02591508813202381, 0.006541190668940544, 0.03384621813893318, 0.012896870262920856, -0.006493353750556707, -0.11023097485303879, 0.0051418389193713665, -0.058800674974918365, 0.06361033767461777, -0.04192933812737465, 0.028800813481211662, -0.02058451808989048, -0.017006950452923775, 0.06571345776319504, -0.0035696837585419416, 0.0021155807189643383, -0.011280292645096779, 0.09026513993740082, -0.02849334105849266, 0.02390344813466072, 0.05478580668568611, 0.07152671366930008, 0.0733681321144104, 0.013061936013400555, -0.02108307182788849, 0.03024118021130562, -0.014088298194110394, 0.03165851905941963, 0.0584317147731781, -0.09666479378938675, 0.044881682842969894, -0.028532765805721283, 0.035187941044569016, -0.1257590502500534, -0.04946797713637352, -0.042443882673978806, -0.03995285928249359, -0.04268694296479225, 0.04721948504447937, -0.01854243315756321, 0.03766382485628128, 0.03744333237409592, 0.012523958459496498, -0.02370445244014263, -0.039674580097198486, -0.057112690061330795, -0.050443343818187714, -0.017826344817876816, -0.06688875705003738, -0.002172253793105483, 0.012296860106289387, -0.013132534921169281, -0.01833399571478367, 0.07338248193264008, -0.010043464601039886, -0.05134638771414757, 0.00710162241011858, -0.09407924860715866, -0.03279814124107361, 0.00012768029409926385, -0.0351017601788044, -0.006234115455299616, 0.058297429233789444, 0.017508065328001976, 0.08352621644735336, -0.04023751989006996, 0.044723253697156906, -0.06792891025543213, 0.04641828313469887, -0.006482754368335009, -0.01939638