INSERT INTO scholarships (name, continent, country, level, description, deadline, category, major, benefit, requirements, source, url, original_url, embedding) VALUES ('Beasiswa Malaysia International Scholarship (MIS)', 'Asia', 'Luar Negeri (Malaysia)', 'S2, S3', 'Berikut dokumen yang harus diunggah (format PDF): Panduan Beasiswa Indonesia Bangkit (BIB) S1', '03 Apr 2026', 'Fully Funded', 'Semua Jurusan', '• Fully Funded • Bebas seluruh biaya perkuliahan hingga selesai masa kuliah • Tunjangan hidup sebesar RM 1.500 per bulan (Rp 6.300.000)', 'Lainnya Persyaratan Beasiswa: Merupakan warga negara dari negara penerima beasiswa MIS (termasuk Indonesia). Berminat melanjutkan studi pascasarjana (Master atau PhD) di Malaysia. Usia maksimal: 40 tahun untuk program Master 45 tahun untuk program PhD IPK minimal 3.00 atau setara Second Class Upper (Honours) untuk pelamar Master. Untuk PhD, pelamar harus memiliki IPK minimal 3.00 atau hasil akademik yang sangat baik pada jenjang Master. Kemampuan bahasa Inggris dengan salah satu bukti berikut: IELTS minimal 6.0, atau TOEFL PBT minimal 550, atau Pernah kuliah dengan bahasa pengantar Inggris. Untuk Master by Research dan PhD, wajib menyertakan proposal penelitian minimal 1000 kata. Dokumen Berikut dokumen yang harus diunggah (format PDF): Formulir pendaftaran online. Salinan paspor yang masih berlaku minimal 6 bulan. Transkrip akademik resmi: Transkrip S1 untuk pelamar Master Transkrip S1 dan S2 untuk pelamar PhD Bukti kemampuan bahasa Inggris (IELTS/TOEFL atau surat bahasa pengantar). 2', 'Luarkampus', 'https://biasiswa.mohe.gov.my/INTER/index.php#', 'https://biasiswa.mohe.gov.my/INTER/index.php#', '[-0.005954207386821508, 0.09209829568862915, -0.03452092409133911, -0.013896427117288113, -0.028756460174918175, -0.027908077463507652, -0.04641103744506836, -0.001052393577992916, 0.008124093525111675, 0.020185094326734543, 0.040556151419878006, -0.03320973366498947, -0.04633216932415962, -0.016242967918515205, -0.01604204438626766