INSERT INTO scholarships (name, continent, country, level, description, deadline, category, major, benefit, requirements, source, url, original_url, embedding) VALUES ('National Institute of Genetics Fellows in Japan', 'Asia', 'Luar Negeri (Jepang)', 'S3', 'DOKUMEN YANG HARUS DISIAPKAN Semua digabung jadi 1 PDF: Panduan Beasiswa Indonesia Bangkit (BIB) S1', '01 Jul 2026', 'Fully Funded, Riset, Exchange', 'Semua Jurusan', '• Fully Funded • Riset • Tunjanga tahunan sebesaar 4.100.000 (Rp 442.000.000) • Tunjangan transportasi • Asuransi kesehatan', 'Dokumen DOKUMEN YANG HARUS DISIAPKAN Semua digabung jadi 1 PDF: Form 1 CV Nama lab yang dituju Desired starting date Form 2 Summary of past research (1 halaman) Form 3 List of publications & achievements (no page limit) Form 4 (Total 5 halaman) Research Plan at NIG Purpose & background (1 hlm) Research outline (2 hlm) Creative ideas (1 hlm) 3-year annual plan (1 hlm) Tambahan: Reference letter dari supervisor (langsung dikirim ke NIG) Reference dari Host PI Maksimal 3 representative papers (opsional) Lainnya Kirim via email ke: 📧 nigshien@nig.ac.jp Lainnya Syarat Pendaftaran Telah memperoleh gelar PhD (atau setara) atau akan mendapatkannya sebelum tanggal mulai kerja. Memiliki kemampuan riset yang cukup untuk menjalankan proyek di bidang genetika. Tidak memiliki riwayat enrollment di NIG per 31 Maret 2025 (kecuali kunjungan sementara seperti internship). Booklet', 'Luarkampus', 'https://wa.me/6287737395461', 'https://wa.me/6287737395461', '[-0.08184453845024109, 0.016574662178754807, -0.08872455358505249, -0.04960653558373451, -0.013923197984695435, -0.031084276735782623, -0.04163266345858574, 0.03283387050032616, -0.06654860824346542, -0.018484996631741524, 0.10122641175985336, -0.05350068211555481, -0.09452246874570847, -0.018156060948967934, -0.026487285271286964, 0.05164661630988121, -0.09034572541713715, 0.040659308433532715, -0.03434193506836891, -0.13885903358459473, 0.004705892875790596, 0.00025162831298075616, 0.09