INSERT INTO scholarships (name, continent, country, level, description, deadline, category, major, benefit, requirements, source, url, original_url, embedding) VALUES ('James Buchanan Fellowship', 'Amerika', 'Luar Negeri (Amerika Serikat)', 'S3', 'Persyaratan Umum James Buchanan Fellowship: Panduan Program Nutrifood Research Center Fellowship', '15 Apr 2026', 'Riset', 'Semua Jurusan', '• Riset • Tunjangan bulanan • Akomodasi selama program • Biaya perjalanan • Dukungan penuh aktivitas akademik berkaitan dengan riset', 'Lainnya Persyaratan Umum James Buchanan Fellowship: Pelamar berasal dari semua kewarganegaraan (international applicants diperbolehkan). Wajib memiliki gelar PhD (Doktor). Telah menyelesaikan program PhD dalam 6 tahun terakhir. Berstatus sebagai: Peneliti di lembaga riset bereputasi, atau Akademisi/dosen di universitas terakreditasi. Termasuk kategori early-career academic. Memiliki minat kuat pada: Political economy Riset atau pengajaran dalam ilmu sosial, ekonomi, atau kebijakan publik. Bersedia mengikuti program fellowship selama 1 tahun penuh di Amerika Serikat. Mampu berpartisipasi aktif dalam kegiatan akademik, riset, dan diskusi ilmiah. Booklet Informasi Selengkapnya', 'Luarkampus', 'https://www.mercatus.org/students/james-buchanan-fellowship#2392643287-2729856584', 'https://www.mercatus.org/students/james-buchanan-fellowship#2392643287-2729856584', '[-0.08853806555271149, -0.046210091561079025, -0.08762537688016891, -0.006112595554441214, 0.024133624508976936, 0.03131493553519249, -0.07244324684143066, 0.032966867089271545, 0.04847382754087448, -0.016492629423737526, 0.020608043298125267, -0.013852350413799286, -0.06364226341247559, -0.11498989164829254, -0.06566454470157623, -0.0033165677450597286, 0.047558654099702835, 0.02577049285173416, -0.016610417515039444, -0.09292254596948624, 0.04159893840551376, -0.007403807248920202, -0.0009177009924314916, -0.006978713907301426, 0.020344259217381477, 0.03923380747437477, 0.003952607978135347, -0.1