INSERT INTO scholarships (name, continent, country, level, description, deadline, category, major, benefit, requirements, source, url, original_url, embedding) VALUES ('Beasiswa S1, S2 & S3 Pemerintah Kazakhstan', 'Asia & Eropa', 'Luar Negeri (Kazakhstan)', 'S1, S2, S3', 'Special Requirements (Persyaratan Khusus):', '31 Mei 2026', 'Fully Funded', 'Semua Jurusan', '• Fully Funded • Biaya Kuliah Penuh • Tunjangan Bulanan S1 Sebesar 52.372 KZT hingga 84.000 KZT (Rp. 1.780.648 - Rp. 2.856.000) • Tunjangan Bulanan S2 Sebesar 117.098 KZT (Rp. 3.981.332) • Tunjangan Bulanan S3 Sebesar 262.500 KZT (Rp. 8.925.000)', 'Lainnya General Requirements (Persyaratan Umum): Belum pernah menempuh jenjang pendidikan yang dituju. Paspor. Menyerahkan ijazah dan transkrip pendidikan sebelumnya (dengan terjemahan resmi). Menulis esai motivasi (dalam Bahasa Kazakh, Rusia, atau Inggris). Surat rekomendasi minimal dari 1 institusi pendidikan atau tempat kerja. Sertifikat kesehatan lengkap (termasuk tes HIV/AIDS). Mengisi formulir pendaftaran. Surat undangan dari universitas di Kazakhstan (jika ada). Special Requirements (Persyaratan Khusus): IPK minimal 3.0 dari 4.0 atau setara. Sertifikat bahasa asing (misalnya IELTS/TOEFL). Dokumen ijazah disertai dalam bahasa pengantar (Kazakh, Rusia, atau Inggris). Untuk PhD/S3 harus dalam bahasa Inggris. Booklet Informasi Selengkapnya', 'Luarkampus', 'https://bolashak.gov.kz/kz/ctipendiyaly-badarlama', 'https://bolashak.gov.kz/kz/ctipendiyaly-badarlama', '[-0.05264146253466606, 0.007021427620202303, -0.031333114951848984, -0.11377169191837311, -0.0275218915194273, -0.005728867370635271, -0.04175761714577675, 0.014387840405106544, -0.0036853065248578787, -0.000939768913667649, 0.02715878374874592, -0.06329238414764404, 0.045451268553733826, 0.012555288150906563, -0.00032666782499291003, -0.03995555639266968, 0.03180361166596413, 0.01754908822476864, 0.022497083991765976, -0.1224915161728859, 0.005974121391773224, -0.1074201762676239, 0.05405749753117561, 