INSERT INTO scholarships (name, continent, country, level, description, deadline, category, major, benefit, requirements, source, url, original_url, embedding) VALUES ('Leeds Beckett University Global Award Scholarship', 'Eropa', 'Luar Negeri (Inggris)', 'S2', 'For enquiries and support:⁣ Email: LBU-indoscholarship@noblesolutions.Asia⁣ Panduan Beasiswa Indonesia Bangkit (BIB) S1', '30 Apr 2026', 'Fully Funded', 'Semua Jurusan', '• Fully Funded • Pembebasan biaya kuliah penuh • Uang saku sebesar GBP 3,000 (sekitar Rp57.000.000) • Biaya akomodasi • Tiket penerbangan pergi-pulang', 'Lainnya Syarat yang Harus Dipenuhi: Pelamar harus pelajar internasional, artinya bukan berasal dari Inggris. Pelamar harus mendaftar sebagai mahasiswa S2 penuh waktu (bukan paruh waktu) di Leeds Beckett University. Pelamar sudah diterima di universitas ini, baik dengan syarat tertentu (conditional) maupun tanpa syarat (unconditional). Lainnya Program Studi yang Tersedia: MA Education MA International Relations MSc Corporate Governance MSc International Trade and Finance MSc Management and Leadership MSc Responsible Tourism Management MSc Sport Performance Analysis Lainnya For enquiries and support:⁣ Email: LBU-indoscholarship@noblesolutions.Asia⁣ Booklet Informasi Selengkapnya', 'Luarkampus', 'https://www.leedsbeckett.ac.uk/scholarships/lbu-global-award-scholarship/%E2%81%A3', 'https://www.leedsbeckett.ac.uk/scholarships/lbu-global-award-scholarship/%E2%81%A3', '[0.05616655945777893, 0.05527879297733307, -0.02602541260421276, -0.02316104620695114, -0.003984475042670965, 0.010728580877184868, -0.0778333991765976, -0.024175627157092094, 0.034441687166690826, -0.010961351916193962, -0.025978034362196922, -0.01803480088710785, -0.12271402031183243, 0.042794838547706604, -0.01091744750738144, 0.004625214263796806, -0.04736514389514923, -0.016891317442059517, -0.03860792890191078, -0.04191188886761665, 0.03670337423682213, -0.036033496260643005, -0.037801217287778854, -0.0032288534566760063, -0.0