INSERT INTO scholarships (name, continent, country, level, description, deadline, category, major, benefit, requirements, source, url, original_url, embedding) VALUES ('Beasiswa Monbukagakusho (MEXT) Pemerintah Jepang', 'Asia', 'Luar Negeri (Jepang)', 'S2, S3', 'Beasiswa Monbukagakusho (MEXT) Pemerintah Jepang | Negara: Luar Negeri (Jepang) | Jenjang: S2, S3', '22 Apr 2026', 'Fully Funded', 'Pendidikan', '• Fully Funded • Bebas seluruh biaya perkuliahan hingga selesai masa kuliah • Tunjangan hidup ¥143.000 (Rp15.774.840) per bulan untuk research student • Tunjangan hidup S2 ¥144.000 (Rp15.885.120) per bulan • Tunjangan hidup S3 ¥145.000 (Rp15.995.400) per bulan • Tiket pesawat PP Indonesia - Jepang • Bebas biaya pengurusan visa • Asrama (tergantung kebijakan kampus)', 'Lainnya Persyaratan: Usia maksimal 34 tahun pada 1 April 2027 (lahir ≥ 2 April 1992) Lulusan D4 / S1 / S2 Memilih bidang studi yang linear dengan pendidikan sebelumnya IPK minimal 3.2 Memiliki salah satu sertifikat bahasa berikut: TOEFL iBT minimal 72 IELTS minimal 5.5 TOEIC L&R minimal 785 TOEIC S&W minimal 310 JLPT minimal N2 Sertifikat TOEFL harus dari ETS (bukan prediction) Sertifikat IELTS hanya dari lembaga resmi (Cambridge, British Council, IDP, IALF) Tidak menerima NAT-TEST / J-TEST / Duolingo Sehat jasmani dan rohani Memiliki minat kuat belajar budaya & bahasa Jepang Memiliki motivasi kuat untuk melakukan penelitian di Jepang Booklet Informasi Selengkapnya', 'Luarkampus', 'https://www.mext.go.jp/', 'https://www.mext.go.jp/', '[-0.039361920207738876, 0.07304732501506805, -0.020957114174962044, -0.019210604950785637, -0.03151819854974747, -0.06479279696941376, 0.08269597589969635, 0.06331000477075577, 0.04271645471453667, -0.00307324412278831, 0.04998501390218735, -0.09558988362550735, -0.013613112270832062, 0.01527620293200016, -0.008358240127563477, -0.03474057465791702, -0.07934310287237167, 0.05205275118350983, -0.030671151354908943, -0.05894368886947632, -0.01540419366210699, -0.0766905099