INSERT INTO scholarships (name, continent, country, level, description, deadline, category, major, benefit, requirements, source, url, original_url, embedding) VALUES ('The University Of New South Wales Unsw Unsw Scholarships For International Students', 'Australia/Oseania', 'Luar Negeri (Australia)', 'S1', 'Beasiswa - The University of New South Wales (UNSW) - UNSW Scholarships for International Students untuk jenjang S1 dengan tipe Partially Funded di Australia', '26 Februari 2026', 'Partially Funded', 'Matematika, Statistika, Fisika, Ilmu Kebumian, Kimia, Ilmu Alam Terapan, Astronomi, Psikologi Klinis, Ilmu Kedokteran, Ilmu Biomedis, Kesehatan Masyarakat, Farmasi, Kedokteran Hewan, Teknik Elektro, Teknik Mesin, Teknik Komputer, Teknik Sipil, Teknik Kimia, Teknik Dirgantara, Teknik Pertambangan dan Perminyakan, Teknik Industri, Ilmu Material dan Teknik, Teknik Lingkungan, Teknik Biomedis, Psikologi, Hukum dan Studi Hukum, Bahasa dan Sastra, Antropologi, Studi Komunikasi, Studi Budaya dan Agama, Filsafat, Ilmu Humaniora, Studi Gender, Mode / Fashion, Desain Visual, Musik, Seni Visual, Media, Industrial Design, Administrasi Bisnis, Manajemen Bisnis, Pemasaran, Manajemen Sumber Daya Manusia, Manajemen Organisasi, Manajemen Rantai Pasok dan Logistik, Arsitektur, Perencanaan Kota, Desain Interior', '• International Scientia Coursework Scholarship (PUCA1025): • Offer 1: Full tuition fee scholarship paid directly towards tuition fees for the minimum duration of program • Offer 2: $20,000 per annum paid directly towards tuition fees for the minimum duration of program', 'AGE No age requirement GPA No GPA requirement ENGLISH TEST IELTS: min. 7 TOEFL iBT: min. 94 TOEFL PBT NATIONALITY Indonesian OTHER LANGUAGE Not required STANDARDIZED TEST Not required DOCUMENTS Transcript Award Certificates Certificate of Employment/Internship Proof of English Proficiency https://www.scholarships.unsw.edu.au/sites/default/files/uploads/Supporting%20Documentation%20Guide%20-%20UNSW%20Schol