INSERT INTO scholarships (name, continent, country, level, description, deadline, category, major, benefit, requirements, source, url, original_url, embedding) VALUES ('Universit Cattolica Del Sacro Cuore Unicatt Ucsc International Scholarship', 'Eropa', 'Luar Negeri (Italia)', 'S1', 'Beasiswa - Università Cattolica del Sacro Cuore (UNICATT) - UCSC International Scholarship untuk jenjang S1 dengan tipe Partially Funded di Italy', '25 Februari 2026', 'Partially Funded', 'Bisnis, Keuangan, Komunikasi, Kriminologi, Management and Economics, Ilmu Pangan, Hubungan Internasional, Global Affairs, Psikologi', '• For the academic year 2025/26, the tuition and university fee applicable to students who receive the UCSC International Scholarship is € 5,600*. • This scholarship is automatically extended from year to year for the normal duration of the degree programme', 'AGE No age requirement GPA Min. Rapor: 75 out of 100 ENGLISH TEST IELTS: min. 6 TOEFL iBT: min. 84 PTE Academic NATIONALITY Indonesian OTHER LANGUAGE Not required STANDARDIZED TEST Standardized Test (Optional) SAT, ACT, IB, A-Level, AP DOCUMENTS Copy of passport/ID document (single page with your data and photo).If you have an EU and a non-EU passport, upload both Only if applicable: Italian fiscal code Only if applicable: Italian residency permit If you have already graduated from high school: Copy of your official high school diploma* Second-to-last year and last year/current year high school transcripts* The International Admissions Team will get in touch if the third-to-last year transcript is required as well If you are currently enrolled in the last year of high school: Copy of your high school transcript – must include your second-to-last year* Copy of your most up-to-date transcripts for the current year, if available at the time you submit your application* The International A', 'Schoters', 'https://www.schoters.com/id/beasiswa/universit-cattolica-del-sacro-cuore-unicatt-ucsc-international-scholarship-306', 'https://international.unicatt.it/ucscinternational-scholarships', '[0.0040343147702515125, 0.00012528846855275333, -0.040417566895484924, 0.0007137326756492257, -0.011383412405848503, -0.02505592443048954, -0.046199165284633636, 0.01053963229060173, 0.02935957908630371, 0.043585266917943954, 0.02326546609401703, -0.013371448963880539, -0.10226673632860184, 0.010106980800628662, -0.08453094214200974, -0.10359949618577957, -0.05955730751156807, -0.012278473004698753, -0.05923661217093468, -0.062265194952487946, 0.004964623134583235, -0.08867866545915604, -0.013532326556742191, 0.005347872618585825, 0.01973985694348812, -0.01666043885052204, -0.03816194832324982, -0.05808885768055916, -0.06413958221673965, -0.04812271147966385, 0.004203454125672579, 0.08233102411031723, 0.054389819502830505, 0.031587496399879456, 0.037790168076753616, 0.03825979679822922, -0.027490979060530663, -0.040752243250608444, -0.017322858795523643, -0.00954366847872734, -0.003083688672631979, -0.022877318784594536, -0.025148101150989532, -0.02182362787425518, 0.048527635633945465, -0.09226793050765991, 0.0028686681762337685, 0.009092682972550392, -0.04138387739658356, -0.020579181611537933, -0.07583092898130417, -0.009768785908818245, 0.07369238883256912, -0.003839199198409915, -0.039182163774967194, 0.03388079255819321, 0.014234937727451324, -0.022332433611154556, -0.04558834806084633, -0.02631238102912903, -0.004868738818913698, -0.011792467907071114, -0.06699549406766891, 0.02510266937315464, 0.013655847869813442, -0.014145146124064922, -0.07673707604408264, 0.0735355094075203, -0.040381237864494324, -0.006703953258693218, 0.08356992900371552, -0.08026134222745895, -0.019697535783052444, 0.056514281779527664, 0.027581533417105675, 0.05446207523345947, 0.06381608545780182, 0.08549580723047256, 0.11484386771917343, 0.007746332790702581, 0.08121581375598907, -0.007332582958042622, 0.014802414923906326, -0.05516574904322624, 0.004882750101387501, 0.027095673605799675, 0.013690577819943428,