INSERT INTO scholarships (name, continent, country, level, description, deadline, category, major, benefit, requirements, source, url, original_url, embedding) VALUES ('Danish Government Scholarship Southern Denmark University', 'Eropa', 'Luar Negeri (Denmark)', 'S2', 'Beasiswa - Danish Government Scholarship - Southern Denmark University untuk jenjang S2 dengan tipe Partially Funded di Denmark', '1 Februari 2026', 'Partially Funded', 'Teknik Mesin, Mekatronika, Teknik Elektronika', '• The scholarship is granted either as full or partial tuition fee waivers. • A partial tuition fee waiver covers the tuition fee for one year (second and fourth semester), and you must pay tuition for the first and third semester. Note that fee waivers cover 30 ECTS per semester. If the number of courses exceed 30 ECTS they are not covered by the fee waiver.', 'AGE No age requirement GPA No GPA requirement ENGLISH TEST IELTS: min. 7 TOEFL iBT: min. 88 NATIONALITY Indonesian OTHER LANGUAGE Not required STANDARDIZED TEST Not required DOCUMENTS Application deposit fee receipt Official Bachelor’s transcripts and diploma in English, Danish, Swedish or Norwegian – must include grades and ECTS/units/credits for each course Course descriptions for the courses on your transcripts Proof of English language proficiency OTHERS No other specific requirements mentioned.', 'Schoters', 'https://www.schoters.com/id/beasiswa/danish-government-scholarship-southern-denmark-university-384', 'https://www.sdu.dk/en/uddannelse/kandidat/scholarships', '[-0.03157028928399086, 0.09235966205596924, 0.024587519466876984, -0.020340660586953163, 0.055692899972200394, 0.012625820934772491, -0.056616924703121185, 0.029849495738744736, 0.03678865358233452, 0.021989328786730766, 0.01838821917772293, -0.057498108595609665, -0.03062315471470356, -0.03666823357343674, -0.053498148918151855, -0.04229825362563133, -0.02266424335539341, -0.009856258518993855, -0.014792789705097675, -0.04107614606618881, -0.046599727123975754,