INSERT INTO scholarships (name, continent, country, level, description, deadline, category, major, benefit, requirements, source, url, original_url, embedding) VALUES ('Radboud University Radboud Scholarship Programme And Nl Scholarship', 'Eropa', 'Luar Negeri (Belanda)', 'S2', 'Beasiswa - Radboud University - Radboud Scholarship Programme and NL Scholarship untuk jenjang S2 dengan tipe Partially Funded di Netherlands', '31 Januari 2026', 'Partially Funded', 'Matematika, Fisika, Astronomi, Ilmu Biologi, Ilmu Biomedis, Psikologi, Hukum dan Studi Hukum, Bahasa dan Sastra, Antropologi, Studi Komunikasi, Studi Budaya dan Agama, Filsafat, Studi Regional, Seni Rupa, Ekonomi, Ilmu Komputer, Kecerdasan Buatan, Sistem Informasi, Administrasi Bisnis, Manajemen Sumber Daya Alam, Studi Lingkungan Umum, Hubungan Internasional, Administrasi Publik, Ilmu Politik', '• A Radboud Scholarship will reduce your tuition fee to €2,695.-. For example: a grant holder in 2026/2027 will pay a tuition fee of only €2,695.- instead of €18,000 (depending on your programme). The scholarship also covers costs for visa, residence permit, health insurance and liability insurance for your stay in the Netherlands (Aon Student Insurance). The costs of living and studying in the Netherlands are not covered by the scholarship.', 'AGE No age requirement GPA No GPA requirement ENGLISH TEST IELTS: min. 7 TOEFL iBT: min. 92 NATIONALITY Indonesian OTHER LANGUAGE Not required STANDARDIZED TEST Not required DOCUMENTS For scholarship : Two reference letters Curriculum vitae For admission (General) : Bachelor''s degree Transcript Sworn Translation Documents needed for admission are different based on the programme. Kindly check : https://www.ru.nl/english/education/masters-programmes/start-application/students-with-an-international-degree/ OTHERS The NL Scholarship (NLS) will always be combined with the Radboud Scholarship Programme (RSP). This means that students applying for the NLS must also apply for the RSP. You can be awarded both the NLS and RSP, or just the RSP. You cannot be awarded just the NLS.', 'Schoters', 'https://www.schoters.com/id/beasiswa/radboud-university-radboud-scholarship-programme-and-nl-scholarship-405', 'https://www.ru.nl/en/education', '[0.019052021205425262, -0.03668641671538353, -0.043478500097990036, -0.022878985852003098, 0.046321552246809006, 0.032268911600112915, -0.08555945008993149, 0.06282965838909149, -0.008666605688631535, 0.03306719660758972, 0.04834666848182678, -0.031737975776195526, -0.06890750676393509, -0.028618481010198593, -0.06926687806844711, -0.012305042706429958, -0.059482794255018234, -0.02373896725475788, -0.10326359421014786, -0.0692816823720932, -0.018031533807516098, -0.028532402589917183, 0.027518365532159805, -0.0547778345644474, 0.002861465560272336, -0.05464102327823639, -0.04849160090088844, -0.0035412022843956947, -0.015858201310038567, 0.001619627233594656, 0.03733181208372116, 0.07737188041210175, -0.013642815873026848, -0.018919983878731728, 0.0022651851177215576, 0.023920251056551933, -0.0511101633310318, -0.020873911678791046, -0.010534575209021568, 0.053545307368040085, 0.027778083458542824, -0.05064927786588669, -0.028491754084825516, -0.027676939964294434, 0.08175118267536163, -0.07308484613895416, -0.10951519757509232, -0.034190814942121506, -0.003991867881268263, 0.04348868876695633, -0.13509823381900787, -0.06997774541378021, 0.026411207392811775, 0.02882431074976921, 0.013557076454162598, -0.06035442650318146, -0.0381603017449379, 0.00037100445479154587, -0.07798557728528976, -0.03208107873797417, -0.008728626184165478, 0.02991314046084881, -0.06786425411701202, -0.015350154601037502, 0.024001747369766235, -0.0579233355820179, -0.02148102968931198, 0.017627928406000137, 0.06773483008146286, 0.06541923433542252, 0.07043579965829849, -0.05118618160486221, -0.030858395621180534, 0.08107514679431915, -0.04727055877447128, 0.05837611109018326, -0.0007910784333944321, 0.05098087713122368, 0.10228531807661057,