INSERT INTO scholarships (name, continent, country, level, description, deadline, category, major, benefit, requirements, source, url, original_url, embedding) VALUES ('University Of Science And Technology Of China Ustc Fellowship For Master S Programs', 'Asia', 'Luar Negeri (China)', 'S2', 'Beasiswa - University of Science and Technology of China - USTC Fellowship for Master''s Programs untuk jenjang S2 dengan tipe Fully Funded, Partially Funded di China', '31 Januari 2026', 'Fully Funded', 'Astronomi, Atmospheric Sciences, Geology, Geophysics, Administrasi Bisnis, Electronic Information Engineering, Optics and Mechatronics Engineering, Fisika', '• ●  Level A, funded by Ministry of Education (Chinese Government Scholarship), Chinese Academy of Sciences (CAS-ANSO Scholarship) or USTC, includes tuition waiver, Comprehensive Medical Insurance, monthly stipend of 3,000 RMB and accommodation subsidy; • ●  Level B, funded by USTC, includes tuition waiver. Subsidy for Teaching Assistance or Research Assistance will be available for application after enrollment.', 'AGE Max Age: 35 GPA No GPA requirement ENGLISH TEST IELTS TOEFL iBT NATIONALITY Indonesian OTHER LANGUAGE HSK: HSK Level 5 STANDARDIZED TEST Not required DOCUMENTS ● Photocopy of passport (ordinary passport with validity of at least one year) ● A study or research proposal (no less than 1000 words) ● Curriculum Vitae ● Two letters of recommendation from full professors or associate professors (with phone number and email address) ● Foreigner Physical Examination Form (download in the Annex) ● Applicants for programs instructed in Chinese must provide the photocopy of HSK certificate (at least level 4) or other proof of their Chinese language proficiency; applicants for programs instructed in English must provide the photocopy of valid IELTS or TOEFL result or other proof of their English proficiency (except those whose mother tongue is English). ● Photocopy of degree certificate and academic transcripts for both Bachelor''s Degree and Master''s Degree (if have) notarized by Ministry of E', 'Schoters', 'https://www.schoters.com/id/beasiswa/university-of-science-and-technology-of-china-ustc-fellowship-for-master-s-programs-415', 'https://ic.ustc.edu.cn/en/v7info.php?Nav_x=16', '[-0.0845341607928276, -0.003256244584918022, 0.08751045167446136, 0.007042956072837114, 0.023042945191264153, -0.17138250172138214, -0.08942390233278275, -0.013927451334893703, 0.006188793107867241, 4.304613685235381e-05, -0.041976913809776306, -0.03453901782631874, -0.007954237051308155, -0.08655999600887299, -0.030701186507940292, 0.04626660794019699, 0.01879107765853405, -0.025480398908257484, 0.043805647641420364, -0.04684486240148544, 0.039852116256952286, -0.02983439341187477, -0.020894603803753853, -0.04864339902997017, -0.032785385847091675, 0.012411084026098251, -0.07022708654403687, 0.03999502584338188, -0.0451178140938282, -0.04861133545637131, 0.05480079725384712, 0.062398672103881836, -0.08458074927330017, 0.032596148550510406, -0.006054053083062172, -0.012833304703235626, 0.010117827914655209, -0.09521926939487457, -0.030133932828903198, -0.0016036155866459012, 0.007308922708034515, -0.006403619423508644, 0.07468041777610779, -0.016982855275273323, 0.07171802967786789, 0.003026639111340046, 0.03788653761148453, -0.04899916425347328, 0.0038820412009954453, -0.05027502775192261, 0.000835516257211566, -0.021007061004638672, -0.017315512523055077, 0.02810910902917385, 0.030014049261808395, 0.12967637181282043, 0.002858171472325921, -0.022004397585988045, 0.0008943377761170268, -0.07456010580062866, 0.0769050344824791, 0.020694922655820847, -0.09473417699337006, -0.0007986901910044253, 0.02293662540614605, 0.0037998815532773733, -0.0327620655298233, 0.008039646781980991, 0.05260152369737625, -0.0462152473628521, 0.0038730052765458822, 0.0677037313580513, -0.04196399077773094, -0.012973529286682606, 0.007583905011415482, 0.016427036374807358, 0.07375765591859818, 0.05562001094222069, 0.1127477