INSERT INTO scholarships (name, continent, country, level, description, deadline, category, major, benefit, requirements, source, url, original_url, embedding) VALUES ('Mext University Recommendation Yokohama National University Special Program International Priority Graduate Programs Pgp', 'Asia', 'Luar Negeri (Jepang)', 'S3', 'Beasiswa - MEXT University Recommendation - Yokohama National University - Special Program: International Priority Graduate Programs (PGP) untuk jenjang S3 dengan tipe Fully Funded di Japan', '21 Januari 2026', 'Fully Funded', 'International Economics, Comparative Economics, International Political Economy, Ekonomi', '• MEXT shall allocate scholarships and international travel funding to Japan. In addition, the PGP scholarship recipients will receive a tuition waiver from YNU. The PGP scholarship provides a monthly stipend of 148,000 yen (subject to change) for three IPhD students for up to three years of study (contingent upon excellent academic performance).', 'AGE Max Age: 34 GPA Min. GPA: 3.3 out of 4.00 ENGLISH TEST IELTS: min. 6 TOEFL iBT: min. 79 NATIONALITY Indonesian OTHER LANGUAGE Not required STANDARDIZED TEST Not required DOCUMENTS 1. Application for Japanese Government Scholarship (duplex, i.e., double-sided, printing) pdf 2. Field of Study and Research Plan (duplex, i.e., double-sided, printing) word pdf 3. Photograph (4.5×3.5 cm, taken within the past six months, upper body, full-faced, no hats. Write your name and nationality on the reverse side and paste it onto the application form. Digital photographs also acceptable). 4. Abstract of thesis or research paper 5. Recommendation from a high-ranking person such as the dean of a department, the program director, or a person in an equivalent position at the last university attended addressed to Dr. UMEHARA Izuru, President, Yokohama National University. OTHERS No other specific requirements mentioned.', 'Schoters', 'https://www.schoters.com/id/beasiswa/mext-university-recommendation-yokohama-national-university-special-program-international-priority-graduate-programs-pgp-438', 'https://www.urban.ynu.ac.jp/english/all-english-program/special-graduate-program/application-guideline.html', '[-0.01180787943303585, -0.033864788711071014, 0.041921745985746384, -0.014511547051370144, 0.05131080374121666, -0.0014527535531669855, -0.030203714966773987, 0.07536923140287399, -0.04233516752719879, 0.02650749869644642, -0.03507300838828087, -0.008511988446116447, -0.08893143385648727, 0.020181821659207344, 0.04196517542004585, -0.05812876671552658, 0.01564585417509079, -0.013108273036777973, -0.007694132626056671, -0.14914076030254364, 0.010141137056052685, -0.07689198106527328, 0.0381501242518425, -0.09203410148620605, 0.047367654740810394, -0.06754116714000702, 0.053597137331962585, 8.407136192545295e-06, 0.048273537307977676, 0.00302907545119524, -0.053346842527389526, 0.07292671501636505, 0.042311396449804306, -0.0626673772931099, 0.022658856585621834, 0.05665098875761032, -0.0052558681927621365, -0.08238901197910309, -0.049758393317461014, -0.029077652841806412, -0.06734723597764969, 0.01937125436961651, -0.027682246640324593, -0.10834763944149017, 0.03392347693443298, -0.056343261152505875, -0.004425062797963619, -0.04662885144352913, 0.0007036036695353687, -0.024798410013318062, -0.06906639039516449, -0.021063227206468582, 0.04002651199698448, -0.025775760412216187, 0.03940746933221817, 0.018215736374258995, 0.0038592179771512747, 0.02283124066889286, -0.008320001885294914, -0.050786685198545456, -0.04873701184988022, -0.026853103190660477, -0.0694393664598465, -0.03384404256939888, 0.03180668503046036, 0.011393794789910316, -0.004240070935338736, 0.12938325107097626, -0.07361605018377304, 0.0009315413772128522, 0.05307839438319206, -0.06234193965792656, -0.11027763038873672, 0.038081176578998566, -0.014052324928343296, -0.05994685739278793, 0.05373423174023628, 0.08208965510129929, 0.038323212414979935, 0.023308752104640007, 0.052658770233392715