INSERT INTO scholarships (name, continent, country, level, description, deadline, category, major, benefit, requirements, source, url, original_url, embedding) VALUES ('Erasmus Mundus Joint Master Degree In Data Engineering And Artificial Intelligence Deai', 'Asiu', 'Luar Negeri (Perancis, Austria, Italia)', 'S2', 'Beasiswa - Erasmus Mundus Joint Master Degree in Data Engineering and Artificial Intelligence (DEAI) untuk jenjang S2 dengan tipe Fully Funded di Austria, France, Italy', '13 Januari 2026', 'Fully Funded', 'Ilmu Data, Kecerdasan Buatan, Ilmu Komputer', '• The scholarship for students from Partner Countries comprises: • Participation costs: up to 9,000 euros per year • Contribution to travel and subsistence costs: 1,400 euros per month for the entire duration of the DEAI programme (24 months maximum). • Contribution to subsistence costs will neither be given to scholarship holders for the periods of the DEAI programme (study, research, internship, or thesis preparation) spent in the country of residence of the student, nor to scholarship holders from a Partner Country for the periods of the DEAI programme spent in any Partner Country exceeding three months. • The participation costs covering the tuition fees are directly taken by the consortium. The remainder of the scholarship will be allocated to selected students in 24 monthly instalments of 1,400 euros, paid by bank transfer. • All scholarship holders will receive an insurance meeting the insurance requirements of the Erasmus+ programme for JMDs.', 'AGE No age requirement GPA No GPA requirement ENGLISH TEST IELTS: min. 6 TOEFL iBT: min. 72 TOEFL CBT TOEFL PBT NATIONALITY Indonesian OTHER LANGUAGE Not required STANDARDIZED TEST Not required DOCUMENTS Photo Cover letter Passport CV Main Bachelor Certificate Official transcripts for the main bachelor Self-evaluation for the main bachelor Other Bachelor/Master certificate Other official transcript Self-evaluation for other degrees A certificate or proof of English proficiency optional: Bachelor/Master thesis Other certificate Letter of reference 1, 2 and 3 OTHERS No other specific requirements mentioned.', 'Schoters', 'https://www.schoters.com/id/beasiswa/erasmus-mundus-joint-master-degree-in-data-engineering-and-artificial-intelligence-deai-538', 'https://erasmus-plus.ec.europa.eu/', '[-0.06439652293920517, -0.011168273165822029, 0.05083075165748596, 0.027148215100169182, -0.005418277345597744, -0.14413291215896606, -0.06444811820983887, 0.006067870184779167, -0.05958936735987663, -0.00891775544732809, -0.017428655177354813, 0.0024524887558072805, 0.0677601769566536, -0.10408080369234085, -0.02913845144212246, 0.08648569881916046, -0.031275685876607895, -0.024359673261642456, -0.02199043333530426, -0.12284433096647263, 0.03393079340457916, -0.007593461312353611, -0.012945662252604961, -0.10592672973871231, 0.04307061806321144, 0.03522731363773346, 0.08412089943885803, 0.017730887979269028, -0.027481375262141228, -0.05213932693004608, 0.03443019092082977, 0.03253024443984032, -0.05881235748529434, 0.048351652920246124, 0.004462237469851971, -0.06695717573165894, -0.010881862603127956, -0.036668986082077026, 0.03387923538684845, 0.04964563623070717, 0.005643798038363457, 0.03059103526175022, -0.01685595139861107, -0.03991568461060524, 0.05075297877192497, 0.009922400116920471, -0.01660912297666073, -0.04203485697507858, -0.025332892313599586, 0.01623520441353321, -0.07670119404792786, 0.02590297721326351, 0.04128009453415871, -0.03675983101129532, -0.020526953041553497, 0.02324102632701397, 0.02124555967748165, 0.020985255017876625, -0.03727623447775841, 0.038280025124549866, -0.003471494885161519, 0.012109631672501564, -0.03139606863260269, 0.0022327543701976538, 0.01431405358016491, -0.03411576524376869, 0.01195838488638401, 0.054563961923122406, -0.05829267203807831, -0.060856129974126816, 0.021471278741955757, -0.01719442568719387, -0.09155573695898056, 0.036948081105947495, 0.056168556213378906, -0.01662979647517