INSERT INTO scholarships (name, continent, country, level, description, deadline, category, major, benefit, requirements, source, url, original_url, embedding) VALUES ('Beasiswa IDCloudHost 2026 Kuliah Gratis Sampai Lulus di Telkom University', 'Asia', 'Dalam Negeri (Indonesia)', 'S1', 'Beasiswa IDCloudHost adalah program kerja sama antara IDCloudHost dan Telkom University yang memberikan bantuan biaya pendidikan bagi calon mahasiswa berprestasi, khususnya di bidang teknologi, untuk mendukung pengembangan talenta digital.', '31 Mei 2026', 'Fully Funded', 'Fakultas Teknik Elektro (FTE) Fakultas Rekayasa Industri (FRI) Fakultas Informatika (FIF) Fakultas Ekonomi dan Bisnis (FEB) Fakultas Komunikasi dan Ilmu Sosial (FKS) Fakultas Industri Kreatif (FIK) Fakultas Ilmu Terapan (FIT)', '• Gratis biaya pendaftaran  • Gratis seluruh biasa kuliah selama 4 tahun di Telkom University hingga lulus • Kesempatan magang hingga peluang bekerja di IDCloudHost untuk mengembangkan keterampilan dan pengalaman profesional di Industri Teknologi • Kesempatan membangun jaringan profesional di industri teknologi melalui workshop, seminar dan komunitas IDCloudHost', '1. Program besiswa ini dibuka bagi Siswa/I lulusan SMA/SMK/MA Sederajat kelas 12 (yang akan lulus tahun 2026) 2. Beasiswa ini juga dapat diikutin lulusan SMA/SMK/MA Sederajat (gap year) tahun 2022,2023,2024, dan 2025', 'indbeasiswa', 'https://indbeasiswa.com/beasiswa-idcloudhost/', 'https://indbeasiswa.com/beasiswa-idcloudhost/', '[-0.029808586463332176, -0.012994477525353432, -0.05735461413860321, -0.05897854268550873, -0.03963528946042061, -0.035553909838199615, 0.04048340767621994, 0.05553208291530609, -0.00915609486401081, 0.01989060826599598, 0.001298805931583047, -0.023849518969655037, -0.0005886059952899814, -0.07937099039554596, 0.040658045560121536, -0.0448480099439621, -0.0033234073780477047, -0.06731464713811874, -0.04767045006155968, -0.10501731932163239, 0.01804182305932045, -0.08442393690347672, -0.00072760105831548