INSERT INTO scholarships (name, continent, country, level, description, deadline, category, major, benefit, requirements, source, url, original_url, embedding) VALUES ('Beasiswa S3 UNHAN 2026', 'Asia', 'Dalam Negeri (Indonesia)', 'S3', 'Beasiswa doktoral dari Universitas Pertahanan Indonesia yang mencakup biaya pendidikan penuh dan fasilitas pendukung.', '05 Juni 2026', 'Fully Funded', 'Konsesntrasi strategi pertahanan Konsentrasi manajemen pertahanan konsentrasi keamanan nasional konsentrasi teknologi pertahanan konsentrasi kesehatan pertahanan', '• Biaya kuliah selama masa studi di UNHAN GRATIS • Disediakan juga uang saku dan fasilitas lainnya', '1. merupakan warga negara indonesia. Dibuka untuk laki-laki dan perempuan 2. sehat jasmani dan rohani 3. berusia tidak lebih dari 45 tahun bagi peserta masyarakat umum dan tidak lebih dari 53 tahun bagi peserta dari TNI/KAPOLRI/ASN/BUMN 4. Lulusan pendidikan program S-2 dari Perguruan Tinggi yang terakreditasi minimal "Baik Sekali" 5. Memiliki IPK pendidikan program S-2 minimal 3,50 6. diutamakan bagi peserta yang belum pernah mendapatkan beasiswa pendidikan program doktor (S-3) dari pemerintah', 'indbeasiswa', 'https://indbeasiswa.com/beasiswa-s3-unhan/', 'https://indbeasiswa.com/beasiswa-s3-unhan/', '[-0.0514976941049099, 0.024658581241965294, -0.03495583310723305, -0.05750565603375435, -0.058340124785900116, 0.02907230146229267, -0.07427386194467545, -0.06666236370801926, 0.03088507056236267, 0.017373211681842804, 0.04912790283560753, -0.0014514208305627108, -0.0690213218331337, -0.02425267919898033, 0.028792917728424072, -0.059473928064107895, -0.05070130527019501, -0.0030833303462713957, -0.020762022584676743, -0.07540099322795868, 0.07399878650903702, -0.02250153198838234, -0.05422491580247879, 0.0026348205283284187, 0.012281494215130806, 0.0050841341726481915, 0.04101528599858284, -0.04423915967345238, 0.04242103546857834, 0.011515024118125439, -0.01702350750565529, 0.10514915734529495, -0.016933534294366837, -0.02