INSERT INTO scholarships (name, continent, country, level, description, deadline, category, major, benefit, requirements, source, url, original_url, embedding) VALUES ('Beasiswa S2 UNHAN 2026', 'Asia', 'Dalam Negeri (Indonesia)', 'S2', 'Beasiswa doktoral dari Universitas Pertahanan Indonesia yang mencakup biaya pendidikan penuh dan fasilitas pendukung.', '05 Juni 2026', 'Fully Funded', 'Magister strategi perang semesta magister peperangan asimetris magister diplomasi pertahanan magister strategi pertahanan laut magister ekonomi pertahanan magister ketahanan energi magister manajemen bencana magister keamanan maritim', '• Bebas biaya pendaftaran serta biaya perkuliahan selama pendidikan di UNHAN • Disediakan tempat tinggal, makanan 3x sehari, snack, pakaian dinas dan pakaian olahraga UNHAN • Uang saku untuk masing-masing penerima beasiswa • Kuliah Kerja Dalam Negeri (KKDN) dan Kuliah Kerja Luar Negeri (KKLN) • Biaya penelitian tesis dan biaya lainnya terkait dengan pendidikan', '1. merupakan warga negara indonesia. Dibuka untuk laki-laki dan perempuan 2. sehat jasmani dan rohani 3. berusia tidak lebih dari 45 tahun bagi peserta masyarakat umum dan tidak lebih dari 53 tahun bagi peserta dari TNI/KAPOLRI/ASN/BUMN 4. Lulusan pendidikan program S-2 dari Perguruan Tinggi yang terakreditasi minimal "Baik Sekali" 5. Memiliki IPK pendidikan program S-2 minimal 3,50 6. diutamakan bagi peserta yang belum pernah mendapatkan beasiswa pendidikan program doktor (S-3) dari pemerintah', 'indbeasiswa', 'https://indbeasiswa.com/beasiswa-unhan-s2/', 'https://indbeasiswa.com/beasiswa-unhan-s2/', '[-0.005034007132053375, 0.04497799277305603, -0.05022382363677025, -0.030483610928058624, -0.06430941820144653, 0.04191501438617706, -0.03691915422677994, -0.006227070465683937, -0.028555825352668762, -0.0280007254332304, 0.06707019358873367, -0.006049181800335646, -0.055503781884908676, -0.038979098200798035, -0.00910301972180605, -0.06486835330724716, -0.0046750083565711975, 0.011381264775991