INSERT INTO scholarships (name, continent, country, level, description, deadline, category, major, benefit, requirements, source, url, original_url, embedding) VALUES ('Beasiswa S2 Manajemen tahun 2026 oleh PPM School of Management FULL Scholarship', 'Asia', 'Dalam Negeri (Indonesia)', 'S2', 'Beasiswa magister bidang manajemen yang memberikan bantuan biaya kuliah sebagian bagi lulusan S1.', '28 Mei 2026', 'Fully Funded', 'Magister Manajemen', '• Bebas biaya perkuliahan S2 secara penuh • mendapatkan uang saku selama 20 bulan pendidikan • mendapatkan modul, E-BOOK, dan Jurnal • Jejaring profesional dan kegiatan mentoring • mendapatkan kesempatan untuk on the job training • kesempatan untuk ikut serta dalam berbagai macam kompetisi bisnis dan penulisan kasus dengan bimbingan dosen atau praktisik PPM  ', '1. Merupakan warga negara indonesia  2. berusia maksimal 26 tahun per 1 september2026 3. belum menikah & tidak akan menikah selama masa program (OJT) 4. Lulusan S1 atau D4 (lulus paling lambat pada 1 Agustus 2026) dari perguruan tinggi dan prodi dalam dan luar negeri 5. mempunyai IPK S1 minimal 3,00 6. Mempunyai kemampuan bahasa Inggris ditunjukkan dengan minimal skor TOEFL : 500 atau IELTS: 6 dari lembaga tes bahasa inggris dan masih dalam masa berlaku', 'indbeasiswa', 'https://indbeasiswa.com/beasiswa-s2-manajemen/', 'https://indbeasiswa.com/beasiswa-s2-manajemen/', '[-0.02942688763141632, 0.05801580846309662, -0.0028194489423185587, 0.0021441292483359575, -0.0502883717417717, 0.006993409246206284, -0.04403061792254448, -0.028924500569701195, -0.03203950077295303, 0.019647132605314255, 0.075562983751297, -0.0003483413893263787, -0.05000917986035347, -0.035683561116456985, 0.013494495302438736, -0.047018006443977356, -0.03198425844311714, 0.0019535941537469625, -0.006917840801179409, -0.08397767692804337, 0.047525957226753235, -0.06101955100893974, -0.0015978117007762194, -0.011474271304905415, -0.09459609538316727, 0.014163827523589134, 0.04665925353765488, 0.0147175