INSERT INTO scholarships (name, continent, country, level, description, deadline, category, major, benefit, requirements, source, url, original_url, embedding) VALUES ('Beasiswa BSI Sholarship Unggulan', 'Asia', 'Dalam Negeri (Indonesia)', 'S1', 'BSI Scholarship Unggulan adalah program beasiswa S1 dari BSI Maslahat dan Bank Syariah Indonesia yang memberikan pembiayaan penuh kuliah dan pembinaan kepemimpinan bagi mahasiswa berprestasi di PTN terbaik hingga lulus.', '2026-04-12 00:00:00', 'Fully Funded', 'Semua Jurusan', 'full cover biaya pendidikan dari semester 1 hingga lulus (8 semester) uang saku sampai dengan Rp 1.500.000 per bulan selama masa studi fasilitas laptop untunk menunjang kebutuhan akademik program pembinaan kepemimpinan & pengembangan karakter berkelanjutan kesempatan magang di industri perbankan & ekonomi syariah', '1. mahasiswa baru top 10 perguruan tinggi negeri jalur SNBP atau undangan sejenis 2. memiliki prestasi akademik unggul 3. berasal dari keluarga kurang mampu (dibuktikan dengan SKTM/DTKS) 4. tidak sedang menerima beasiswa sejenis dari lembaga lain 5. memiliki komitmen untuk mengikuti program pembinaan hingga lulus', 'beasiswaindo', 'https://beasiswaindo.com/scholarships/bsi-scholarship-unggulan/', 'https://linktr.ee/BSI_Scholarship', '[-0.03021571785211563, 0.059104543179273605, -0.0179632306098938, -0.0010867316741496325, -0.08193877339363098, -0.005558797158300877, -0.0031013493426144123, -0.04122740775346756, -0.014914648607373238, -0.017210781574249268, 0.03679157420992851, -0.044193558394908905, -0.06579308956861496, -0.08850327134132385, -0.013469882309436798, -0.04026927798986435, -0.0740530714392662, -0.00447686854749918, -0.07385352998971939, -0.08307085931301117, -0.019065450876951218, -0.0523410364985466, 0.0034875657875090837, -0.004141509998589754, 0.00406860513612628, -0.04017515853047371, 0.0409260056912899, -0.015160550363361835, 0.03386879712343216, -0.03239231929183006, 0.029354311525821686, 0.07781103253364563, -0.026780