INSERT INTO scholarships (name, continent, country, level, description, deadline, category, major, benefit, requirements, source, url, original_url, embedding) VALUES ('Beasiswa VDMI untuk Mahasiswa D3,D4 dan S1', 'Asia', 'Dalam Negeri (Indonesia)', 'D3, D4, S1', 'Beasiswa VDMI adalah program bantuan pendidikan dalam negeri dari Yayasan Van Deventer-Maas Indonesia yang memberikan dana bulanan dan pelatihan pengembangan diri bagi mahasiswa D3, D4, dan S1 berprestasi dari keluarga kurang mampu hingga masa studi selesai.', '10 Maret 2026', 'Partially Funded', 'Akuntansi, Pertanian, Peternakan, Arsitektur,  Seni dan Budaya, Biologi, Kimia, Komunikasi,  Ekonomi, Penidikan, Teknik, Bahasa Inggris,  Manajemen Keuangan, Kehutanan, Sosiologi,  Informatika, Manajemen, Matematika, Fisika, Hukum dan Ilmu Politik', '• bantuan dana senilai Rp 800.000 setiap bulan yang dibayarkan kepada rekening pribadi penerima beasiswa • satu kali Bonus TOEFL dan Bonus Lulus tepat waktu • mendapatkan pelatihan pengembangan kapasitas pribadi melalui proses seleksi. Seluruh biaya ditanggung oleh VDMI', '1. merupakan mahasiswa D4/S1 semester 2 s.d 6 dan mahasiswa D3 semester 2 s.d 4 2. berusia maksimal 27 tahun. 3. berasal dari keluarga dengan ekonomi tiak mampu, dibuktikan dengan SKTM 4. memilki IPK > 3.00 5. aktif berorganisasi di komunitas sosial 6. lebih diutamakan bagi mereka yang fasih berbahasa inggris 7. tidak sedang mendapatkan beasiswa lainnya', 'beasiswaindo', 'https://beasiswa.id/2026/beasiswa-vdmi-untuk-mahasiswa-d3-d4-dan-s1/', 'https://beasiswa.id/2026/beasiswa-vdmi-untuk-mahasiswa-d3-d4-dan-s1/', '[0.0013712256914004683, 0.03378588333725929, -0.008567718788981438, -0.07785066962242126, -0.04639790579676628, 0.007035205140709877, -0.036720991134643555, 0.024984775111079216, 0.0012319451197981834, 0.04156375676393509, 0.07684183865785599, -0.019009005278348923, -0.055259544402360916, -0.01603887230157852, 0.04457816481590271, -0.02999448962509632, 0.008717596530914307, 0.0236916746944