INSERT INTO scholarships (name, continent, country, level, description, deadline, category, major, benefit, requirements, source, url, original_url, embedding) VALUES ('beasiswa kartu indonesia pintar kuliah (KIP Kuliah)', 'Asia', 'Dalam Negeri (Indonesia)', 'D3, D4,S1', 'Program Beasiswa', '31 oktober 2026', 'Fully Funded,  Partially Funded', 'Semua Jurusan', 'Biaya Pendidikan Full Sampai Lulus Biaya Hidup Bulanan Biaya Pendaftaran Seleksi Masuk Perguruan Tinggi', 'Siswa Sekolah Menengah Atas (SMA), Sekolah Menengah Kejuruan (SMK), Madrasah Aliyah (MA) atau sederajat yang akan lulus pada tahun penyelenggaraan program atau telah lulus maksimal 2 tahun yang lalu. Memiliki potensi akademik yang baik dan keterbatasan ekonomi dibuktikan dengan pendapatan kotor gabungan orang tua atau wali paling banyak Rp4.000.000 setiap bulan atau pendapatan kotor gabungan orang tua atau wali dibagi jumlah anggota keluarga paling banyak Rp750.000. Telah lulus seleksi penerimaan mahasiswa baru di Perguruan Tinggi Negeri (PTN) atau Perguruan Tinggi Swasta (PTS) di program studi yang telah terakreditasi A atau B. Mahasiswa baru yang diterima di program studi terakreditasi C diperbolehkan untuk mendaftar dengan pertimbangan tertentu.', 'luarkampus.id', 'https://luarkampus.id/beasiswa/781', 'https://kip-kuliah.kemdiktisaintek.go.id/siswa/auth/login', '[-0.006308014038950205, 0.04600326344370842, -0.020853595808148384, -0.07583265751600266, -0.08218846470117569, -0.021990466862916946, -0.03692258149385452, -0.05522920936346054, -0.011347354389727116, 0.030848292633891106, 0.06620612740516663, -0.05621642619371414, -0.05701446533203125, -0.035740047693252563, 0.004949222318828106, 0.005132936406880617, -0.03503423184156418, 0.01065841130912304, -0.023486949503421783, -0.08835510909557343, -0.017176907509565353, -0.04474455118179321, -0.015983091667294502, -0.021102450788021088, -0.00629459461197257, 0.048731978982686996, 0.08016727864742279, 0.021450676023960114, 0.04361513629555702, -0.06841