INSERT INTO scholarships (name, continent, country, level, description, deadline, category, major, benefit, requirements, source, url, original_url, embedding) VALUES ('Beasiswa Tahfidz Universitas Nahdlatul Ulama Yogyakarta (UNU Jogja)', 'Asia', 'Dalam Negeri (Indonesia)', 'S1', 'Program Beasiswa', '2026-09-14 00:00:00', 'Fully Funded,  Partially Funded', 'Semua Jurusan', 'Bebas seluruh biaya perkuliahan hingga selesai masa kuliah bagi penghafal 30 Juz Bebas 75% biaya perkuliahan hingga selesai masa kuliah bagi penghafal 20 Juz Bebas 50% biaya perkuliahan hingga selesai masa kuliah bagi penghafal 15 Juz', 'Pendaftar merupakan penghafal Al-Qur''an dengan hafalan minimal 15 juz Berlaku untuk semua program studi Pendaftar wajib mengikuti media sosial instagram atau tiktok UNU Yogyakarta Seleksi menggunakan data nilai rapor semester 1 - 5 Nilai minimal mata pelajaran pada semester 5 yaitu Bahasa Inggris adalah 70 dan Matematika 70, serta rata-rata nilai rapor adalah 70 Bagi pendaftar Program Studi Farmasi, Informatika, dan Teknik Elektro harus berasal dari lulusan jurusan IPA atau jurusan lain yang relevan Bagi pendaftar Program Studi Farmasi harus memiliki nilai MIPA (kimia, biologi, fisika, dan matematika) minimal 80. Bagi pendaftar Program Studi Studi Islam Interdisipliner Fakultas Dirasah Islamiyah harus lancar membaca Al-Quran, serta dapat membaca, menulis dan memahami Bahasa Arab tingkat dasar Bersedia untuk tidak membongkar diri atau cuti selama masa studi setelah mendapatkan NIM dan dinyatakan sebagai mahasiswa baru (dibuktikan dengan berkenan menitipkan ijazah asli kepada Universitas) Bersedia memiliki IPK >= 3.0 (jika IPK tidak mencapai 3.0 maka membayar biaya kuliah semester berikutnya akan seperti biaya UKT 1) Keputusan tim seleksi PMB tidak bisa diganggu gugat', 'luarkampus.id', 'https://luarkampus.id/beasiswa/2443', 'https://admisi.unu-jogja.ac.id/login', '[-0.006623194552958012, 0.050119247287511826, -0.013132591731846333, 0.0020111112389713526, -0.05039