INSERT INTO scholarships (name, continent, country, level, description, deadline, category, major, benefit, requirements, source, url, original_url, embedding) VALUES ('Beasiswa Wakaf Produktif', 'Asia', 'Dalam Negeri (Indonesia)', 'D3,D4,S1', 'Program Beasiswa', '07 Juli 2026', 'Fully Funded', 'Semua Jurusan', 'Beasiswa Pendidikan Penuh Untuk mahasiswa rumpun ilmu kesehatan (D3, D4, S1, Profesi) di Politeknik/Universitas. Beasiswa Tunjangan Pendidikan sebesar Rp4.000.000/semester (Rp8.000.000/tahun).Untuk semua jurusan (D3, D4, S1) dari Politeknik/Universitas Self-development mentoring. Kesempatan magang/kerja di MHDC Group. Seminar keprofesian.', 'Beasiswa Pendidikan Penuh (Rumpun Ilmu Kesehatan) Mahasiswa D3, D4, S1, Profesi rumpun kesehatan (kedokteran, kedokteran gigi, keperawatan, radiologi, dll). Tidak sedang menerima beasiswa lain yang mengikat. Ikatan dinas 2n+1 tahun di MHDC Group. IPK minimal 3,25. Leadership & komitmen kontribusi untuk wakaf produktif di Indonesia. Bersedia magang & melakukan aksi sosial bila dibutuhkan. Beasiswa Tunjangan Pendidikan (Semua Jurusan) Mahasiswa semua jurusan (D3, D4, S1). Tidak sedang menerima beasiswa lain yang mengikat. Memiliki kemampuan akademik baik & IPK minimal 3,25. Leadership & komitmen kontribusi untuk wakaf produktif di Indonesia. Bersedia magang & melakukan aksi sosial bila dibutuhkan.', 'luarkampus.id', 'https://luarkampus.id/beasiswa/1799', 'https://drive.google.com/drive/folders/1E4EY8EN36TEo83NCwFRmZJPpukKtlQ1x', '[-0.021164940670132637, 0.01325286366045475, -0.06936044991016388, -0.07579103112220764, -0.015185842290520668, 0.0029877466149628162, -0.004033971112221479, 0.02917197346687317, -0.038050588220357895, -0.00290656927973032, 0.0651017501950264, -0.02414071187376976, -0.0641433447599411, -0.039768945425748825, 0.02753208950161934, -0.05811106413602829, -0.024250460788607597, 0.0026678633876144886, -0.0429949052631855, -0.12085498869419098, 0.04339427500963211, -0.039086077362298965, -0.0246198922395