INSERT INTO scholarships (name, continent, country, level, description, deadline, category, major, benefit, requirements, source, url, original_url, embedding) VALUES ('Beasiswa AFS Effect + for the classroom Pembelajaran Online Untuk Guru SMA Sederajat', 'Asia', 'Dalam Negeri (Indonesia)', 'S1', 'Program pertukaran pelajar internasional dari AFS Intercultural Programs yang menyediakan beasiswa dan pengembangan kepemimpinan global.', '14 Januari 2026', 'Fully Funded', 'Semua Jurusan', 'Mendapatkan sertifikat internasional Akses sumber daya pengajaran tentang SDGs dan pendidikan kewarganegaraan global (modul interaktif, video, kuis, slide) Sesi live online dengan rekan global Forum diskusi dengan guru dari berbagai negara Pengalaman metode pengajaran yang berbeda Dibimbing fasilitator AFS Kesempatan mendapat pengakuan internasional atas proyek sosial siswa terkait SDGs', 'Guru SMA/sederajat (usia siswa 14–18 tahun), semua bidang studi Belum pernah ikut Global STEM Educators atau Global Up Educator Mampu mengikuti program dalam bahasa Inggris Tertarik pada pendidikan global & pembangunan berkelanjutan Memiliki minat berinteraksi lintas budaya Bersedia mengikuti program ±2–3 jam/minggu selama 6 minggu Memiliki perangkat (HP/laptop) untuk akses program Memiliki webcam & mikrofon Koneksi internet stabil', 'indbeasiswa', 'https://indbeasiswa.com/beasiswa-afs-effect/', 'https://indbeasiswa.com/beasiswa-afs-effect/', '[-0.0025643371045589447, 0.025925636291503906, -0.05174243450164795, -0.007929976098239422, -0.02916101925075054, 0.020427780225872993, -0.0016769918147474527, -0.005506947636604309, 0.01753377355635166, 0.04130726680159569, 0.09771698713302612, 0.021560093387961388, -0.0634031817317009, -0.020596103742718697, 0.05446383357048035, -0.014862936921417713, -0.0029659911524504423, -0.007830831222236156, -0.07915259897708893, -0.11631690710783005, 0.007385444361716509, -0.0476577989757061, 0.036869924515485764, 0.03508071228861809, -0.047210805118083954, -0.0150653