INSERT INTO scholarships (name, continent, country, level, description, deadline, category, major, benefit, requirements, source, url, original_url, embedding) VALUES ('Beasiswa ILF 2026 Bantuan Biaya Kuliah untuk Calon Mahasiswa Kristen dan Katolik ', 'Asia', 'Dalam Negeri (Indonesia)', 'S1', 'Bagi kamu lulusan SMA/SMK/Sederajat yang beragama Kristen atau Katolik, ada tawaran Beasiswa ILF untuk melanjutkan kuliah S1 di berbagai universitas di Indonesia yang bisa kamu coba! Program ILF Scholarship 2026 ditawarkan oleh Indonesian Leadership Foundation (ILF) bagi lulusan...', '2026-04-15 00:00:00', 'Fully Funded', 'Semua Jurusan', 'Bantuan biaya kuliah (SPP/UKT) per semester sampai maksimal 8 semester (S1). Penerima beasiswa harus mempertahankan IPS minimal 3,0 setiap semester agar bantuan tetap berjalan.', 'Warga Negara Indonesia. Beragama Kristen atau Katolik. Lulusan SMA/SMK/sederajat 2025 atau maksimal 2 tahun sebelumnya (2023, 2024). Tidak sedang atau pernah menjalani perkuliahan di perguruan tinggi sebelumnya. Mempunyai keterbatasan finansial namun potensi akademik dan kepemimpinan yang baik. Bersedia menjadi relawan paruh waktu ILF selama minimal 1 tahun setelah lulus kuliah. Mengisi formulir pendaftaran lengkap dan menyertakan semua dokumen yang diminta.', 'indbeasiswa', 'https://indbeasiswa.com/beasiswa-kuliah-s1-ilf-lulusan-sma-smk/', 'https://indbeasiswa.com/beasiswa-kuliah-s1-ilf-lulusan-sma-smk/', '[-0.014051925390958786, 0.059376850724220276, 0.011727013625204563, -0.06293854117393494, -0.03201949596405029, 0.02141956053674221, -0.05254495143890381, -0.052478909492492676, 0.012650479562580585, 0.046732813119888306, 0.045835595577955246, -0.060718972235918045, -0.05219279229640961, -0.05298643559217453, 0.003139415755867958, -0.03796905651688576, -0.04574086517095566, 0.02210208587348461, -0.1007222831249237, -0.10503410547971725, -0.08600760996341705, -0.05178167298436165, -0.020227333530783653, -0.041608214378356934, -0.05180181562900543, -0.01803631708