INSERT INTO scholarships (name, continent, country, level, description, deadline, category, major, benefit, requirements, source, url, original_url, embedding) VALUES ('Beasiswa Bakti GYA', 'Asia', 'Dalam Negeri (Indonesia)', 'S1,S2,S3', 'Beasiswa Bakti 2026 adalah inisiasi Global Youth Action dalam bentuk bantuan dana pengembangan sebesar Rp5.400.000 yang bersifat fleksibel dan dapat dimanfaatkan untuk menunjang kebutuhan pendidikan maupun peningkatan kapasitas penerima. Program ini dirancang untuk mendorong lahirnya generasi muda yang lebih mandiri, berdaya saing, dan mampu mengoptimalkan potensinya secara berkelanjutan.', '15 Agustus 2026', 'Partially Funded', 'Semua Jurusan', 'Bantuan dana pengembangan sebesar Rp5.400.000', 'Peserta wajib melampirkan berkas persyaratan Beasiswa Bakti GYA, sebagai berikut: 1. Bukti mengkampanyekan program Beasiswa Bakti GYA dengan share poster program pada social media peserta. 2. CV (Curriculum Vitae) 3. Draft Motivation Letter 4. Sertifikat Tes Potensi Akademik (TPA) Belum bisa digantikan dengan sertifikat lain. 5. Sertifikat perlombaan/prestasi (jika ada) Pastikan seluruh berkas dilampirkan dengan lengkap pada tahap pengumpulan berkas pada website globalyouthaction.com', 'Tiktok', 'https://globalyouthaction.com/', 'https://globalyouthaction.com/', '[0.00911776814609766, 0.06613592058420181, -0.03451075032353401, -0.021221473813056946, -0.06711651384830475, 0.034675948321819305, 0.007472694385796785, 0.026800749823451042, -0.034594934433698654, 0.021199524402618408, 0.14555461704730988, -0.0258078183978796, -0.007310076151043177, 0.03569021448493004, 0.05035862699151039, -0.018846841529011726, 0.014188103377819061, -0.006774352863430977, -0.025422153994441032, -0.14149241149425507, -0.0007646630983799696, -0.07072900980710983, -0.011742058210074902, 0.03904857113957405, -0.0367165133357048, 0.023260224610567093, 0.007156697101891041, -0.05008726194500923, 0.029071791097521782, 0.024668008089065552, 0.08486610651016235, 0.120596