INSERT INTO scholarships (name, continent, country, level, description, deadline, category, major, benefit, requirements, source, url, original_url, embedding) VALUES ('Beasiswa 2026 Otorita IKN - Universitas Brawijaya (Rumpun Ilmu Sosial dan Humaniora)', 'Asia', 'Dalam Negeri (Indonesia)', 'S1', 'Panduan Beasiswa Indonesia Bangkit (BIB) S1 Panduan Mendaftar Beasiswa Malaysia International Scholarship', '17 Apr 2026', 'Fully Funded', 'Semua Jurusan', '• Fully Funded • Bebas seluruh biaya perkuliahan hingga selesai masa kuliah • Iuran pengembangan institusi', 'Lainnya Pelamar harus memenuhi syarat berikut: Penduduk wilayah delineasi IKN Dibuktikan dengan KTP atau Kartu Keluarga (KK). Diutamakan berasal dari keluarga kurang mampu Dibuktikan dengan surat keterangan dari kelurahan/desa. Pendidikan Lulusan SMA/SMK/MA atau sederajat tahun 2024–2026 dari sekolah terakreditasi, atau Siswa kelas XII dengan nilai rapor semester 1–5. Nilai rata-rata rapor minimal 80 per semester. Bebas narkoba Dibuktikan dengan Surat Keterangan Bebas Narkoba (SKBN) dari rumah sakit pemerintah. Belum menikah dan bersedia tidak menikah selama masa kuliah. Tidak sedang menerima beasiswa lain. Dokumen Dokumen yang harus disiapkan: Formulir pendaftaran dan surat pernyataan Scan KTP pelamar, KTP orang tua/wali, dan Kartu Keluarga Surat keterangan dari kelurahan/desa (bagi pelamar dari keluarga kurang mampu) Pas foto terbaru ukuran 3×4 Scan ijazah atau surat keterangan kepala sekolah + rapor semester 1–5 (untuk siswa kelas XII) Scan Surat Keterangan Bebas Narkoba (SKBN) Essa', 'Instagram', 'https://www.instagram.com/p/DVsJJXfktbu/?img_index=1', 'https://www.instagram.com/p/DVsJJXfktbu/?img_index=1', '[-0.011699953116476536, 0.08104148507118225, -0.0042170388624072075, -0.01448323205113411, -0.052091680467128754, -0.001232461305335164, -0.035867780447006226, -0.03739779070019722, -0.018975745886564255, 0.028108034282922745, 0.04139856621623039, -0.06990668922662735, -0.05547357350587845, 0.00753112370