INSERT INTO scholarships (name, continent, country, level, description, deadline, category, major, benefit, requirements, source, url, original_url, embedding) VALUES ('Beasiswa Unggulan - Mahasiswa & Masyakarat berprestasi', 'Asia', 'Dalam Negeri (Indonesia)', 'S1, S2, SMA', 'Mahasiswa UIN, khususnya yang baru masuk tahun 2023 dan yang semester 5 tahun ini, sudah bisa mendaftar BU 2025', '27 Jul 2026', 'Fully Funded', 'Pendidikan', '• Fully Funded • Biaya Pendidikan Full Sampai Lulus • Biaya Hidup • Biaya Buku', 'Lainnya diutamakan memiliki sertifikat yang membuktikan prestasi akademik/non akademik tingkat internasional dan/atau nasional; mendapatkan rekomendasi minimal dari guru Bimbingan Konseling di Sekolah asal bagi pendaftar jenjang S-1, dan dari pimpinan perguruan tinggi asal atau pembimbing akademik/skripsi/tesis untuk pendaftar jenjang S- 2/S-3; Tidak sedang mendaftar dan/atau menerima beasiswa dari pihak manapun termasuk APBN/APBD dengan komponen pembiayaan yang sama; Belum pernah menempuh pendidikan pada jenjang yang sama; Diterima di perguruan tinggi dalam negeri yang telah terakreditasi paling rendah B/Baik Sekali dan pada program studi terakreditasi paling rendah B/Baik Sekali, serta masuk dalam daftar Perguruan Tinggi tujuan Beasiswa Unggulan (sebagaimana daftar terlampir) atau di perguruan tinggi di luar negeri yang diakui oleh Direktorat Jenderal Pendidikan Tinggi, Riset, dan Teknologi; Tidak berstatus sebagai dosen, guru, tenaga kependidikan, dan pelaku budaya; dan beasiswa han', 'Luarkampus', 'https://wa.me/6287737395461', 'https://wa.me/6287737395461', '[-0.03763287141919136, 0.031038569286465645, -0.023525889962911606, 0.013192509301006794, -0.08184438198804855, -0.003351425752043724, -0.06108912453055382, -0.030809370800852776, -0.039909373968839645, -0.0023819527123123407, 0.07908130437135696, -0.04897518455982208, -0.08310525864362717, -0.0038549310993403196, -0.015453698113560677, -0.052348338067531586, -0.03693581372499466, -0.0307787768542